-- postpartum week 48: Eating well as breastfeeding changes
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   48,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Eating well as breastfeeding changes',
   '"Whether breastfeeding continues, changes or ends, your nourishment can adjust without becoming a diet."',
   'This week doesn''t introduce a new nutrient. It''s about how your own eating can adjust as breastfeeding changes — whether you''re continuing regular breastfeeding alongside complementary foods, reducing some feeds, combining breast milk and formula, or preparing to stop or having already stopped. At this stage, many babies are eating complementary foods while continuing to breastfeed. Continuing beyond the first birthday is valid, reducing feeds is valid, and stopping for personal or medical reasons is also valid. This week does not assume that any one of those paths is due now. Breastfeeding uses energy and nutrients, but the amount varies with how frequently your baby feeds, how much milk is transferred, your body and your wider circumstances. If feeds reduce, your appetite may change gradually — or it may not change noticeably at first. Neither response means you are doing anything wrong. This is not a cue to count calories, deliberately shrink portions or begin weight-loss dieting. Continue eating regular, satisfying meals and let hunger, fullness, energy and recovery guide gradual adjustments. This remains a nourishment plan for the mother, not a replacement-feeding plan for the baby. If breastfeeding is intentionally stopped before 12 months, replace breast milk with infant formula under the baby''s feeding guidance. Ordinary cow''s milk should not become the baby''s main drink before the first birthday.',
   'If you have diabetes or use insulin or glucose-lowering medicine: changes in breastfeeding, appetite and meal timing may affect glucose patterns differently from person to person. Continue your usual monitoring plan and ask for review if readings or intake change substantially. Do not alter medication or carbohydrate targets solely because a feed has been dropped. If you were treated for iron-deficiency anemia, or your periods are returning: see Day 4 below — your iron needs may look different now, and it''s worth checking with your care team rather than assuming the same plan still applies. However your feeding is going — continuing, changing, or ending by choice, for a medical reason, or because your milk supply didn''t work out the way you''d hoped — that''s valid, and it doesn''t require an explanation to anyone. Ending breastfeeding does not require an apology. Continuing breastfeeding does not require one either.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Notice where you are in your own feeding journey right now — not where you think you \"should\" be by this point. Let today''s plate follow your actual hunger, not an idea of how much you''re \"supposed\" to eat at this stage.", "breakfast_a": "Vegetable paratha with curd", "breakfast_b": "Egg-and-vegetable omelette with toast", "lunch_a": "Rice with a chole (chickpea) curry and a cooked vegetable", "lunch_b": "Chicken-and-chana curry with roti and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with a small handful of walnuts (adult portion — keep whole nuts out of the baby''s reach)", "nourishment_break_b": "Curd with chopped dates and a drizzle of honey, for the mother only — do not share honey with a baby under 12 months", "dinner_a": "Chana-and-vegetable pulao with raita", "dinner_b": "Grilled fish with rice and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "Your appetite may change, or it may not", "notes": "Some mothers notice less hunger as breastfeeding reduces; others notice little immediate change, because sleep, activity, menstrual cycles, stress and individual biology also affect appetite. There is no required amount by which your food should decrease. Respond to your actual hunger rather than cutting food in anticipation.", "breakfast_a": "Idli with sambar", "breakfast_b": "Boiled egg with toast and a seasonal fruit", "lunch_a": "Rice with an urad dal and a cooked vegetable", "lunch_b": "Mutton stew with rice and a cooked vegetable", "nourishment_break_a": "Cooked sprouted-moong salad (never raw) with lemon and chopped tomato", "nourishment_break_b": "Banana with a spoon of peanut butter (adult portion — keep spoonfuls of nut butter out of the baby''s reach)", "dinner_a": "Moong-dal and vegetable khichdi with ghee", "dinner_b": "Paneer bhurji with roti and a cooked vegetable", "still_hungry": "A few plain crackers"}, {"day_number": 3, "title": "When some breastfeeds reduce and others remain", "notes": "Reducing one or more feeds does not create a precise new calorie target, and complementary feeding is not the same thing as ending breastfeeding. Keep your own meals regular and balanced while your appetite and routine find their new pattern.", "breakfast_a": "Besan chilla with curd", "breakfast_b": "Egg bhurji with roti", "lunch_a": "Roti with a sabut moong dal and a sautéed vegetable", "lunch_b": "Chicken frankie (roti wrap) with a side salad", "nourishment_break_a": "Roasted makhana with a glass of milk (adult portion — keep whole makhana and other hard foods out of the baby''s reach)", "nourishment_break_b": "Seasonal fruit with curd", "dinner_a": "Roti with a lauki-chana dal and a cooked vegetable", "dinner_b": "Soy-chunk curry with rice and a sautéed vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 4, "title": "Iron and your changing needs", "notes": "Menstrual bleeding may resume before, during or after breastfeeding changes, and its timing varies widely. Once regular periods return, menstrual blood loss can influence iron needs, but the correct intake or supplement plan depends on your diet, bleeding pattern, symptoms, test results and previous iron status. Worth knowing: Persistent tiredness that doesn''t ease with rest, breathlessness on mild exertion, or pale skin or nail beds are worth mentioning to your care team, rather than assuming they''re just ordinary new-parent fatigue — they can check whether your iron needs any attention right now.", "breakfast_a": "Ragi dosa with sambar or curd", "breakfast_b": "Spinach-and-egg toast", "lunch_a": "Rajma-and-spinach curry with rice, and a squeeze of lemon", "lunch_b": "Chicken-and-spinach curry with rice and a cooked vegetable", "nourishment_break_a": "An orange or another vitamin-C-rich fruit with roasted chana (adult portion — keep whole roasted chana out of the baby''s reach; pairing vitamin C with iron-rich foods, as in today''s meals, helps your body absorb plant-based iron)", "nourishment_break_b": "Curd with a spoon of pumpkin seeds", "dinner_a": "Palak dal with roti", "dinner_b": "Fish curry with rice and a cooked vegetable", "still_hungry": "A small bowl of roasted chana (adult portion — keep whole chana out of the baby''s reach)"}, {"day_number": 5, "title": "If breastfeeding reduces quickly", "notes": "Sometimes breastfeeding reduces or stops faster than planned — for a medical reason, a return to work, or a difficult supply journey. Your eating doesn''t have to match that same fast timeline; let your appetite ease at its own pace over the following days and weeks. When possible, reducing feeds gradually over several weeks is usually more comfortable and lowers the chance of engorgement and mastitis. If feeds must stop more quickly, use a comfortable supportive bra, apply a cold compress for discomfort, and express only enough milk to relieve uncomfortable fullness — not repeatedly to empty the breasts. Worth knowing: If a baby under 12 months suddenly refuses the breast, don''t automatically assume that breastfeeding has naturally ended. Sudden refusal can be a temporary nursing strike, particularly during illness, discomfort or disruption — seek feeding guidance if it persists or intake is a concern. Also seek medical advice if you develop worsening breast pain, spreading redness, fever, feel significantly unwell, or suspect an abscess.", "breakfast_a": "Grilled vegetable sandwich with curd", "breakfast_b": "Chicken sandwich with a side of cut vegetables", "lunch_a": "Lemon rice with dal or curd and a cooked vegetable", "lunch_b": "Egg curry with roti and a cooked vegetable", "nourishment_break_a": "Coconut water with a small bowl of roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)", "nourishment_break_b": "Curd with chopped dates and a few walnuts (adult portion — keep whole nuts out of the baby''s reach)", "dinner_a": "Rice with a green-moong-and-vegetable curry", "dinner_b": "Paneer curry with rice and a cooked vegetable", "still_hungry": "A banana"}, {"day_number": 6, "title": "Small, steady habits — settling in, not rushing", "notes": "There''s no need to force your plate back to exactly how it looked before pregnancy, or to reach some new \"normal\" by a certain date. Most mothers find their eating settles gradually into a steady, comfortable pattern over weeks, not days — let it happen at its own pace.", "breakfast_a": "Vegetable uttapam with sambar or curd", "breakfast_b": "Masala omelette with toast", "lunch_a": "Rice with a mixed-dal (panchmel) curry and a cooked vegetable", "lunch_b": "Fish curry with rice and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with curd and ground roasted flaxseed", "nourishment_break_b": "Curd or milk with roasted sunflower seeds; tea or coffee may be served separately within your caffeine limit", "dinner_a": "Roti with a masoor dal and a cooked vegetable", "dinner_b": "Grilled chicken with rice and a sautéed vegetable", "still_hungry": "A glass of buttermilk"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Wherever you are in your feeding journey — continuing, partway through a change, or already finished — what''s one part of how you''ve been eating these past weeks that you''d like to carry forward?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'As your feeding routine changes, what would it look like to let your eating change just as gradually — without rushing to "fix" anything?',
   'Next week, we''ll look at another everyday pattern worth a closer look.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 49: Eating well as you return to movement
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   49,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Eating well as you return to movement',
   '"Building strength starts with fueling it, not restricting it."',
   'This week doesn''t introduce a new nutrient. It''s about eating in a way that supports movement — whatever that looks like for you right now, from a short walk to a structured workout, or not yet begun at all. There is no single right time to return to exercise after birth, and this week does not assume you''re at any particular point. Gentle movement can often begin when it feels comfortable after an uncomplicated recovery. Structured, strenuous or high-impact exercise may need a more gradual return, particularly if you had medical or surgical complications or still have pain, leaking, pressure, heaviness, persistent abdominal doming or another ongoing symptom. Movement asks something of your body, the same way healing and feeding do — it deserves real fuel, not less food. This isn''t a week about earning your meals through exercise, or about using movement as a shortcut to losing weight quickly. Eating enough, staying hydrated, and resting between sessions all matter as much as the movement itself.',
   'If you had a caesarean birth or significant tearing, or have persistent diastasis recti: the way you return to exercise depends on how you have healed and whether symptoms remain. Seek individual guidance before strenuous or high-impact exercise if you still have pain, wound concerns, pelvic pressure or heaviness, leaking, or persistent abdominal doming. Diastasis does not mean avoiding all core movement; a pelvic health physiotherapist can help you find exercises appropriate for your body. If you have diabetes or use insulin or glucose-lowering medicine: activity can affect glucose patterns, and the response may change with the type, duration and intensity of movement. Follow your usual monitoring plan. If you use insulin or another medicine that can cause low glucose — or your diabetes team has advised it — carry a fast-acting carbohydrate source and know how to treat a low. Ask your diabetes team before changing medication, carbohydrate targets or timing around activity. However much or little movement is part of your life right now, that''s the right amount for you — this week supports whichever path you''re on, not a particular pace.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Notice where you actually are with movement right now — a short walk, structured exercise, or not yet started — rather than where you think you should be. Let today''s plate match what your body is actually doing today, not a future workout plan.", "breakfast_a": "Sprouted-moong-and-vegetable cheela with curd", "breakfast_b": "Boiled egg with toast and a glass of milk", "lunch_a": "Rice with a rajma-and-vegetable curry", "lunch_b": "Chicken curry with roti and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)", "nourishment_break_b": "Curd with a spoon of soaked chia seeds", "dinner_a": "Roti with a moong dal and a sautéed vegetable", "dinner_b": "Fish curry with roti and a cooked vegetable", "still_hungry": "A banana"}, {"day_number": 2, "title": "There''s no fixed timeline", "notes": "There is no single timeline for returning to movement after birth. Some mothers feel comfortable beginning gentle activity early; others need longer, especially after a complicated birth or difficult recovery. Build gradually from where your body is now. Seek individual guidance before strenuous or high-impact exercise if you have ongoing pain, leaking, pelvic pressure or heaviness, persistent abdominal doming, wound concerns or another symptom.", "breakfast_a": "Vegetable daliya (broken-wheat) upma with curd or peas", "breakfast_b": "Egg-and-tomato toast", "lunch_a": "Rice with a chana dal and a cooked vegetable", "lunch_b": "Mutton curry with rice and a cooked vegetable", "nourishment_break_a": "Buttermilk with roasted makhana (adult portion — keep whole makhana out of the baby''s reach)", "nourishment_break_b": "Banana with a spoon of almond butter (adult portion — keep spoonfuls of nut butter out of the baby''s reach)", "dinner_a": "Rice with a mixed-vegetable curry and dal", "dinner_b": "Paneer curry with roti and a cooked vegetable", "still_hungry": "A glass of buttermilk"}, {"day_number": 3, "title": "Fueling before and after you move", "notes": "For a short walk or gentle movement, you may not need any specially timed food — your regular meals and your own hunger may be enough. Before a longer or more demanding session, a familiar carbohydrate-containing snack can support energy. Afterwards, an ordinary meal or snack containing both carbohydrate and protein can support recovery. None of this needs to be complicated or precisely timed.", "breakfast_a": "Stuffed methi paratha with curd", "breakfast_b": "Egg-and-spinach omelette with toast", "lunch_a": "Roti with a toor dal and a sautéed vegetable", "lunch_b": "Chicken-and-vegetable pulao", "nourishment_break_a": "A banana with a small handful of dates, if you want something before a longer or more demanding session", "nourishment_break_b": "Curd with roasted chana after moving, or whenever it fits your hunger (adult portion — keep whole chana out of the baby''s reach)", "dinner_a": "Roti with a chana dal and a sautéed vegetable", "dinner_b": "Fish curry with rice and a cooked vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 4, "title": "Exercise and breastfeeding", "notes": "Regular moderate exercise does not reduce milk production or adversely affect milk composition or infant growth. You do not need to delay breastfeeding after moving — feed your baby whenever they want. Worth knowing: Feeding or expressing before exercise may make your breasts feel more comfortable. Drink according to thirst. If your baby seems bothered by the salty taste of sweat after a particularly sweaty session, rinsing your breast or showering may help, but this is not usually necessary.", "breakfast_a": "Rava idli with sambar or curd", "breakfast_b": "Egg bhurji with toast", "lunch_a": "Rice with a lobia curry and a cooked vegetable", "lunch_b": "Chicken-and-lobia curry with roti and a cooked vegetable", "nourishment_break_a": "Coconut water with a small bowl of roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)", "nourishment_break_b": "Buttermilk with a spoon of roasted sesame seeds", "dinner_a": "Palak dal with rice", "dinner_b": "Grilled fish with roti and a cooked vegetable", "still_hungry": "A few dates"}, {"day_number": 5, "title": "If your recovery has been slower", "notes": "A caesarean birth, significant tearing, or ongoing pelvic floor or core symptoms can mean movement needs more time and individual guidance — that''s a normal, common path, not a setback. Eating enough overall, including regular protein-rich foods, supports tissue healing regardless of when structured exercise itself resumes. Worth knowing: If you notice a visible bulge or doming along your abdominal midline, ongoing heaviness or bulging in your pelvic area, leaking urine, or pain that isn''t settling, mention it to your care team or ask about a pelvic floor physiotherapist before resuming structured exercise.", "breakfast_a": "Oats-and-vegetable uttapam with sambar or curd", "breakfast_b": "Grilled chicken tikka roll", "lunch_a": "Vegetable pulao with raita", "lunch_b": "Chole curry with rice and a cooked vegetable", "nourishment_break_a": "Roasted chana with a glass of milk (adult portion — keep whole chana out of the baby''s reach)", "nourishment_break_b": "Seasonal fruit with curd", "dinner_a": "Rice with a masoor dal and a sautéed vegetable", "dinner_b": "Paneer bhurji with roti and a cooked vegetable", "still_hungry": "A few plain crackers"}, {"day_number": 6, "title": "Strength is built on fuel, not on eating less", "notes": "Using movement to justify eating less works against you — your body needs steady nourishment to build strength and stamina. For ordinary or moderate movement, drink according to thirst and continue your regular meals. Longer sessions, very heavy sweating or hot conditions may require additional fluid or electrolytes, but they are not automatically necessary, and this still is not a week to count calories.", "breakfast_a": "Moong-dal dosa with sambar or curd", "breakfast_b": "Vegetable-and-egg paratha", "lunch_a": "Rice with an urad dal and a cooked vegetable", "lunch_b": "Tandoori-style chicken with rice and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with a glass of milk", "nourishment_break_b": "A glass of milk with roasted sunflower seeds (adult portion — keep whole seeds out of the baby''s reach)", "dinner_a": "Curd rice with dal and a cooked vegetable", "dinner_b": "Palak paneer with roti", "still_hungry": "A small bowl of roasted chana (adult portion — keep whole chana out of the baby''s reach)"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. However movement fits into your life right now — a lot, a little, or not yet — what''s one thing that would make it easier to keep feeding yourself well alongside it?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat movement as something your body deserves fuel for, rather than something you have to earn your food through?',
   'Next week, we''ll look at another everyday pattern worth a closer look.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 50: Eating well if you're thinking about another pregnancy
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   50,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Eating well if you''re thinking about another pregnancy',
   '"Wherever you are on this decision, eating well doesn''t have to wait for an answer."',
   'This week doesn''t introduce a new nutrient of its own. It''s about a decision some mothers are actively weighing around now — whether and when another pregnancy might come next — and how eating well fits around that thinking, whichever way it goes. There''s no single right interval between pregnancies. Guidance from bodies like ACOG generally advises against conceiving again within six months of giving birth, and suggests discussing the risks and benefits of an interval under about 18 months with your care team — but this is a personal decision shaped by your health, your family, and your own readiness, not a rule to follow on its own. What eating well can do, regardless of timing, is support your health now and help address anything that may matter before a future pregnancy. That can include restoring iron status after pregnancy, birth blood loss or resumed periods, and maintaining adequate folate intake. Neither iron nor folic-acid supplements should be treated as a substitute for individual medical guidance. It''s also worth knowing that ovulation can return before your first postpartum period does. By this point, breastfeeding on its own isn''t a reliable way to prevent pregnancy — worth keeping in mind whether or not another pregnancy is something you want right now. If you do not want another pregnancy yet, ask your healthcare professional about a contraceptive option that suits you. If you''re not thinking about another pregnancy now — or ever — the meals still apply to you. Iron-rich and folate-rich foods support ordinary health, but this week does not require you to make a reproductive plan.',
   'If you had a caesarean birth or a complicated delivery: the interval before another pregnancy is worth discussing specifically with your care team, partly because of how your uterine scar has healed — this is individual, and not something a calendar alone can answer. If you''re anaemic or your iron levels haven''t fully recovered: ask about rechecking your iron levels before trying to conceive again, rather than assuming time alone has corrected it — correcting a deficiency beforehand is generally easier than catching up during a new pregnancy. If you have diabetes, prediabetes, or PCOS: if pregnancy may be part of your plans, ask for a preconception review of your glucose pattern, medicines and supplements. Do not change medication or severely restrict carbohydrates on your own. Irregular periods do not mean pregnancy cannot occur. If you have a thyroid condition: thyroid hormone needs typically rise in pregnancy, and levels are usually rechecked and adjusted before or very early in a pregnancy. Ask your care team to review your dose and levels if another pregnancy is part of your plan. If you take levothyroxine, follow your prescribed timing and separate iron or calcium supplements from it by the interval advised by your clinician or pharmacist. However you''re thinking about timing — soon, later, or not at all — that''s your decision to make, not something this week is nudging you toward.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Some mothers reading this are actively weighing another pregnancy; others aren''t thinking about it at all, and both are completely fine. Let today''s plate be about feeding yourself well right now, not about a decision that may or may not be on your mind.", "breakfast_a": "Vegetable poha with peanuts and a squeeze of lemon", "breakfast_b": "Egg-and-capsicum bhurji with toast", "lunch_a": "Rice with a matki (moth bean) curry and a cooked vegetable", "lunch_b": "Chicken do-pyaza with rice and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with roasted walnuts (adult portion — keep whole walnuts out of the baby''s reach)", "nourishment_break_b": "Curd with a spoon of ground roasted flaxseed", "dinner_a": "Roti with a moong-masoor dal and a sautéed vegetable", "dinner_b": "Fish tikka with a sautéed vegetable and roti", "still_hungry": "A few dates"}, {"day_number": 2, "title": "If this isn''t on your mind at all", "notes": "If another pregnancy isn''t something you''re thinking about — now, later, or ever — this week doesn''t need you to. There''s nothing here that requires a plan or a decision; it''s simply what eating well can look like at this point, whichever way things go.", "breakfast_a": "Vegetable dhokla with curd", "breakfast_b": "Masala omelette with roti", "lunch_a": "Rice with a toor dal and lauki (bottle gourd) sabzi", "lunch_b": "Mutton keema with rice and a cooked vegetable", "nourishment_break_a": "Buttermilk with roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)", "nourishment_break_b": "Apple slices with a spoon of almond butter (adult portion — keep spoonfuls of nut butter out of the baby''s reach)", "dinner_a": "Rice with a moong dal and a cooked vegetable", "dinner_b": "Paneer tikka with roti and a cooked vegetable", "still_hungry": "A glass of buttermilk"}, {"day_number": 3, "title": "Replenishing iron, again", "notes": "Iron stores can run low after pregnancy and birth — especially after heavier blood loss during delivery, if you were anaemic beforehand, or once your periods return and start drawing on iron again each month. This is about pregnancy, birth, and your own cycle, not about how you''re feeding your baby. Pairing iron-rich foods with something vitamin-C-rich at the same meal helps your body absorb more of it, so today''s plate leans on that pairing. Worth knowing: If you''re trying to conceive or could already be pregnant, avoid liver and avoid additional supplements containing retinol or high-dose preformed vitamin A. Do not combine multiple prenatal or multivitamin products unless your care team has checked them. Beta-carotene in ordinary foods is not the concern. If you had heavy bleeding, persistent fatigue, breathlessness or previously low iron, ask whether your blood count and iron status should be checked.", "breakfast_a": "Besan-and-spinach cheela with tomato chutney or a squeeze of lemon", "breakfast_b": "Egg-and-tomato bhurji with toast", "lunch_a": "Roti with a rajma curry, a squeeze of lemon, and a sautéed vegetable", "lunch_b": "Mutton curry with roti and a tomato-onion salad with lemon", "nourishment_break_a": "Orange segments with roasted chana (adult portion — keep whole chana out of the baby''s reach)", "nourishment_break_b": "Fresh amla, guava or orange with roasted pumpkin seeds (adult portion — keep whole seeds out of the baby''s reach)", "dinner_a": "Roti with a spinach-and-moong dal, a squeeze of lemon, and a cooked vegetable", "dinner_b": "Chicken curry with rice and a tomato-cucumber salad with lemon", "still_hungry": "A few dates"}, {"day_number": 4, "title": "Folate, again", "notes": "Folate needs rise sharply in early pregnancy, often before most people even know they''ve conceived — which is why the standard advice is to start 400 micrograms of folic acid daily before you begin trying, not after a positive test. If another pregnancy is anywhere in your thinking, this is worth raising with your care team now rather than later. Worth knowing: The standard dose is 400 micrograms daily. A higher dose is sometimes advised — for example, after a previous pregnancy affected by a neural tube defect, with certain medications, or with diabetes — but that decision should be made with your care team, not increased on your own.", "breakfast_a": "Green-moong-and-methi cheela with curd", "breakfast_b": "Egg-and-methi bhurji with toast", "lunch_a": "Rice with a chana-and-spinach curry and a cooked vegetable", "lunch_b": "Chicken-and-methi curry with rice and a cooked vegetable", "nourishment_break_a": "Guava with a small handful of roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)", "nourishment_break_b": "Cooked sprouted-moong salad with lemon and cucumber", "dinner_a": "Roti with a rajma-methi curry and a sautéed vegetable", "dinner_b": "Paneer-and-methi bhurji with roti", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "If you''re breastfeeding during a new pregnancy", "notes": "Breastfeeding can generally continue during an uncomplicated pregnancy if it remains comfortable for you and your child. Continue regular, satisfying meals, drink according to thirst and rest when possible. Pregnancy hormones can reduce milk supply, and this is not something a mother can always prevent by eating more. Worth knowing: At Week 50, your current baby is still under 12 months. If you notice fewer wet nappies, persistent dissatisfaction after feeds, or concerns about growth or milk intake, seek infant-feeding guidance rather than judging supply from breast fullness alone. If breast milk becomes insufficient or breastfeeds stop before 12 months, infant formula may be needed under the baby''s feeding guidance; ordinary cow''s milk should not become the main drink before the first birthday. If the pregnancy involves bleeding, significant pain, risk of preterm birth or another complication, ask the pregnancy care team whether continuing breastfeeding is appropriate.", "breakfast_a": "Multigrain toast with peanut butter and banana slices (adult portion — keep spoonfuls of nut butter out of the baby''s reach)", "breakfast_b": "Egg-and-mushroom bhurji with toast", "lunch_a": "Rice with a whole-moong curry and a cooked vegetable", "lunch_b": "Mutton rogan-josh-style curry with rice and a cooked vegetable", "nourishment_break_a": "A small banana-and-date milkshake (no added sugar) — or roasted nuts with milk instead if you''re watching your glucose", "nourishment_break_b": "Roasted chana chaat with cucumber and tomato (adult portion — keep whole chana out of the baby''s reach)", "dinner_a": "Roti with a masoor-and-spinach dal and a sautéed vegetable", "dinner_b": "Grilled chicken with a cooked vegetable and roti", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "This isn''t a countdown", "notes": "Whatever you decide — trying again soon, waiting years, or not planning another pregnancy at all — that decision is yours, on your own timeline, and this week isn''t trying to nudge you toward any of it. Eating well doesn''t need to wait for a decision either way.", "breakfast_a": "Sabudana khichdi with roasted peanuts and curd", "breakfast_b": "Boiled eggs with a vegetable sandwich", "lunch_a": "Roti with a lobia curry and a sautéed vegetable", "lunch_b": "Tandoori-style paneer with rice and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with roasted almonds (adult portion — keep whole almonds out of the baby''s reach)", "nourishment_break_b": "Buttermilk with roasted chana (adult portion — keep whole chana out of the baby''s reach)", "dinner_a": "Roti with a chana-lauki curry and a sautéed vegetable", "dinner_b": "Chicken bhuna with rice and a cooked vegetable", "still_hungry": "A banana"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Whatever you''re thinking about another pregnancy — soon, later, not at all, or genuinely undecided — what''s one thing you''d want your body to have more of before you''d feel ready, whether or not that day ever comes?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let your eating support your own readiness, on your own timeline, rather than a calendar built for someone else?',
   'Next week, we''ll look at another everyday pattern worth a closer look.')
