  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 53: Eating well when the pressure to "get your body back" begins
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   53,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when the pressure to "get your body back" begins',
   '"Your body carried and fed a whole person this year — it was never lost, and it doesn''t need to be won back."',
   'Somewhere around a baby''s first birthday, a particular kind of pressure tends to sharpen: comments about "getting your body back," ads timed to a season or a sale, or a sense that recovery should be visibly "done" by now. None of that is a signal about your health — it''s timing, not evidence. There is no single medically required appearance—or universal timetable—for a mother''s body after birth. Weight, shape, appetite and recovery vary considerably between women. Severe restriction or rapid weight-loss diets can leave a mother under-fuelled and may be particularly difficult while breastfeeding. Regular, adequate meals are a safer foundation. Breastfeeding energy needs vary according to feeding frequency, activity, health and individual circumstances, so appetite and personalised medical advice matter more than a fixed calorie rule. Persistent distress about body shape or weight can affect emotional wellbeing and has been associated with depressive symptoms during pregnancy and the postpartum period. If these thoughts are becoming frequent, overwhelming or are changing how you eat, move or relate to yourself, they deserve compassionate support. If you notice yourself skipping meals, hiding what or how much you eat, feeling significant guilt after eating, or exercising to "earn" food, that''s worth raising with a trusted professional. This week''s meals aren''t a substitute for that kind of individualized support.',
   'If you have a history of disordered eating, or you''re noticing new patterns like skipping meals, secretive eating or guilt around food: treat that as a cue to reach out to a trusted healthcare provider or therapist rather than pushing through it alone — this series can''t replace that kind of individualized care. If you''re still breastfeeding: your energy needs may remain higher than before pregnancy, depending partly on how frequently your child feeds and how much milk is being produced. Avoid severe restriction and let hunger, energy and individual guidance shape your intake. If you have PCOS, diabetes, prediabetes or thyroid disease: keep following the monitoring and treatment plan you already have with your care team; a body-image milestone like a birthday isn''t a medical reason to change medication or targets on your own. However your body has changed this year, and however you feel about it today — you don''t owe anyone a "before and after," and this week''s meals are about steady nourishment, not a race back to anywhere.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Whatever your body looks like right now isn''t a problem waiting for a solution. It did an enormous amount of work this year, and today''s meals are simply about feeding the person you actually are — not the one an ad or a comment thinks you should be chasing.", "breakfast_a": "Vegetable dalia (broken wheat) with roasted almonds and a small bowl of curd", "breakfast_b": "Egg-and-spinach omelette with toast", "lunch_a": "Rice with a lauki-chana dal and a cooked vegetable", "lunch_b": "Fish curry with rice and a sautéed vegetable", "nourishment_break_a": "Seasonal fruit with roasted walnuts (adult portion — keep whole walnuts out of the baby''s reach)", "nourishment_break_b": "Fully cooked sprouted-moong chaat with lemon", "dinner_a": "Roti with a lobia (black-eyed pea) curry and a cooked vegetable", "dinner_b": "Chicken curry with roti and a cooked vegetable", "still_hungry": "A boiled egg"}, {"day_number": 2, "title": "If you''re still breastfeeding", "notes": "Nursing your child past their first birthday doesn''t change what regular meals are for: keeping you fuelled, not building or maintaining any particular shape. Eat according to hunger, not according to a calendar or a comment someone made.", "breakfast_a": "Vegetable uttapam with sambar or curd", "breakfast_b": "Egg-and-tomato bhurji with jowar roti", "lunch_a": "Rice with a matki (moth bean) curry and a cooked vegetable", "lunch_b": "Prawn curry with rice and a cooked vegetable", "nourishment_break_a": "Coconut water with roasted almonds (adult portion — keep whole almonds out of the baby''s reach)", "nourishment_break_b": "Dates with a glass of buttermilk", "dinner_a": "Roti with a masoor dal and a sautéed vegetable", "dinner_b": "Egg curry with roti and a cooked vegetable", "still_hungry": "A small bowl of fully cooked sprouts"}, {"day_number": 3, "title": "If you''ve stopped breastfeeding", "notes": "If you''re not breastfeeding — whether that ended recently or a while back — your appetite is still your own best guide, not a chart of how much less you should now be eating. Regular meals matter exactly as much as they did in week one.", "breakfast_a": "Moong-besan chilla with coriander chutney", "breakfast_b": "Vegetable-and-egg toast", "lunch_a": "Roti with a vegetable kadhi and a cooked vegetable", "lunch_b": "Chicken-and-spinach curry with rice", "nourishment_break_a": "Roasted chickpeas with an orange (adult portion — keep whole chickpeas out of the baby''s reach)", "nourishment_break_b": "Curd with a spoon of roasted pumpkin seeds", "dinner_a": "Roti with a chana dal and a sautéed vegetable", "dinner_b": "Fish curry with roti and a cooked vegetable", "still_hungry": "A few roasted makhana (adult portion — keep whole makhana out of the baby''s reach)"}, {"day_number": 4, "title": "When \"get your body back\" talk comes from someone close to you", "notes": "A relative''s comment, a friend''s compliment about \"finally losing the weight,\" or a stranger''s remark can land hard, even when well meant. You''re allowed to redirect the conversation, say nothing, or simply let it pass without treating it as instruction for what to eat today. Worth knowing: If comments about your body are frequent enough to affect your mood, your eating, or how you feel about yourself, it''s worth naming that to someone you trust — a partner, a friend, or a professional. You don''t have to manage that weight alone.", "breakfast_a": "Poha with peanuts", "breakfast_b": "Egg-and-capsicum toast", "lunch_a": "Rice with a chole curry and a cooked vegetable", "lunch_b": "Mutton curry with rice and a cooked vegetable", "nourishment_break_a": "Roasted watermelon seeds with a banana (adult portion — keep whole seeds out of the baby''s reach)", "nourishment_break_b": "Guava with roasted chana (adult portion — keep whole chana out of the baby''s reach)", "dinner_a": "Roti with a green moong dal and a cooked vegetable", "dinner_b": "Paneer bhurji with roti and a cooked vegetable", "still_hungry": "A glass of milk"}, {"day_number": 5, "title": "Movement without a body project attached", "notes": "If you''re moving more these days — walking, a class, chasing a toddler — let food follow that energy rather than trying to offset it. Movement here is about capability and enjoyment, not a transaction to earn dinner.", "breakfast_a": "Vegetable oats idli with sambar or curd", "breakfast_b": "Egg-and-mushroom toast", "lunch_a": "Rice with a horse gram (kollu) curry and a cooked vegetable", "lunch_b": "Chicken-and-drumstick curry with rice and a cooked vegetable", "nourishment_break_a": "Guava with roasted cashews (adult portion — keep whole cashews out of the baby''s reach)", "nourishment_break_b": "Curd with a spoon of roasted sesame seeds", "dinner_a": "Roti with a chana masala and a cooked vegetable", "dinner_b": "Prawn masala with roti and a cooked vegetable", "still_hungry": "A banana"}, {"day_number": 6, "title": "If old habits start creeping back in", "notes": "For some mothers, this looser stage can also loosen old, less helpful patterns — skipping meals to \"make up for\" something, weighing yourself repeatedly, or feeling like today''s food has to correct yesterday''s. None of that has to become routine again; noticing it early is enough reason to ask for support. Worth knowing: A pattern that persists — restriction, bingeing, purging, compulsive exercise, or intense guilt around food — deserves proper support rather than willpower. Speak with your doctor or a mental-health professional; this is common enough to ask about directly, and help works.", "breakfast_a": "Ragi dosa with tomato chutney and sambar or curd", "breakfast_b": "Vegetable-and-egg paratha", "lunch_a": "Rice with a toor dal and a mixed-bean curry", "lunch_b": "Egg-and-potato masala with rice and a cooked vegetable", "nourishment_break_a": "Roasted makhana with an apple (adult portion — keep whole makhana out of the baby''s reach)", "nourishment_break_b": "Buttermilk with roasted jeera powder", "dinner_a": "Roti with a chana-methi dal and a sautéed vegetable", "dinner_b": "Chicken-and-capsicum curry with rice", "still_hungry": "A few dates with a glass of milk or unsweetened fortified plant drink"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. What''s one thing you''d want to say to a mother who feels she should already have her \"old body back\" by now — and can you offer yourself that same sentence?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it feel like to let this body simply be the one you''re living in right now — worth feeding well, without needing to look any particular way to deserve it?',
   'Next week continues Nourish''s next stage, still built around the same idea: your plate matters on its own terms, not as a reward or a correction for how you look.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 54: Eating well as your period returns
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   54,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well as your period returns',
   '"A returning cycle is another change to notice—not a recovery score, and not a cue to restrict what your body is asking for."',
   'Many mothers notice their period returning sometime in this first or second year, sometimes as early as a few months after birth and sometimes well beyond a year, particularly if still breastfeeding. There''s no single correct timeline, and where you fall on it isn''t something diet controls. Once periods resume, menstrual blood loss can add to ongoing iron needs. Iron remained important while periods were absent, particularly after pregnancy and birth; its regular inclusion may become even more relevant when bleeding returns. Some women notice greater hunger or stronger food cravings before a period. Research has found higher average energy intake during the luteal phase, although experiences vary considerably between people and cycles. Strict "cycle-syncing" meal plans are popular, but tightly structured phase-by-phase eating isn''t well supported by current evidence. Steady, adequate meals with enough protein, fat, fibre and key minerals cover most cycle-related needs more reliably than a rigid schedule. It''s also worth remembering that ovulation can happen before a period visibly returns, so the absence of a period isn''t a guarantee about fertility either way — relevant if you''re avoiding or hoping for another pregnancy right now.',
   'If your period hasn''t returned yet: continued breastfeeding can delay its return, and timing varies considerably. But if you are no longer breastfeeding — or the absence is unexpected for your feeding pattern, contraception or health history — mention it to your healthcare provider. No particular food is proven to restart a period, and pregnancy should be considered because ovulation can occur before the first visible period. If your periods have returned heavier, more painful or more irregular than before pregnancy: mention this to your care team rather than assuming it will settle on its own — it''s a reasonable thing to have checked rather than a normal condition of new motherhood. If you have anaemia, a history of heavy periods, or new fatigue since your cycle returned: continue any iron monitoring or supplement plan already agreed with your care team, and mention the change so it can be reviewed rather than adjusting it yourself. Wherever your cycle is right now — absent, irregular, or back to its old rhythm — that''s simply where your body is, not a score on how well you''ve recovered.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Somewhere in this first or second year, many mothers notice their period returning — sometimes earlier, sometimes much later, sometimes with little warning at all. There''s no fixed schedule it''s supposed to follow, and today''s meals don''t need to change because of where you are in that process.", "breakfast_a": "Vegetable paratha with curd", "breakfast_b": "Egg-and-onion omelette with toast", "lunch_a": "Rice with a moong-masoor dal and a cooked vegetable", "lunch_b": "Fish curry with rice and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)", "nourishment_break_b": "Buttermilk with roasted cumin and roasted chana (adult portion — keep whole chana out of the baby''s reach)", "dinner_a": "Roti with a rajma curry and a cooked vegetable", "dinner_b": "Chicken curry with rice and a cooked vegetable", "still_hungry": "A boiled egg"}, {"day_number": 2, "title": "If your period hasn''t returned yet", "notes": "Whether you''re breastfeeding, back at work, or both, it''s common for your period to take months longer to return than a friend''s did, or not to have returned at all yet. Continued breastfeeding can explain a long delay, but if you''ve stopped breastfeeding, aren''t pregnant or on period-suppressing contraception, and your period still hasn''t returned, that''s worth mentioning to your care team rather than assuming it will sort itself out.", "breakfast_a": "Moong dal cheela with mint chutney", "breakfast_b": "Egg-and-vegetable bhurji with toast", "lunch_a": "Rice with a channa dal and a sautéed vegetable", "lunch_b": "Mutton-and-potato curry with roti and a cooked vegetable", "nourishment_break_a": "Coconut water with roasted chana (adult portion — keep whole chana out of the baby''s reach)", "nourishment_break_b": "Dates with a small bowl of curd", "dinner_a": "Roti with a lauki-moong dal and a cooked vegetable", "dinner_b": "Egg curry with rice and a cooked vegetable", "still_hungry": "A few roasted peanuts (adult portion — keep whole peanuts out of the baby''s reach)"}, {"day_number": 3, "title": "If your period has returned", "notes": "Once periods resume, menstrual blood loss can add to ongoing iron needs. Iron remained important while periods were absent, particularly after pregnancy and birth; its regular inclusion may become even more relevant now that bleeding has returned. Pairing iron-rich lentils, beans and greens with vitamin-C-rich fruit can help your body absorb more of the non-haem iron they carry. Diagnosed anaemia still needs proper assessment and prescribed supplementation from your care team — food alone isn''t a substitute for that.", "breakfast_a": "Spinach-and-egg toast with an orange or guava", "breakfast_b": "Ragi porridge with nuts and a small bowl of curd", "lunch_a": "Rice with a lemon-rajma curry and a leafy green vegetable", "lunch_b": "Keema (minced mutton) curry with rice and a cooked vegetable", "nourishment_break_a": "Dates with ground roasted sesame seeds and an orange (adult portion — keep whole seeds out of the baby''s reach)", "nourishment_break_b": "Guava or orange with roasted chana (adult portion — keep whole chana out of the baby''s reach)", "dinner_a": "Roti with a lemon-chana-spinach curry and a cooked vegetable", "dinner_b": "Mutton curry with roti and a leafy green vegetable", "still_hungry": "A small bowl of curd with dates"}, {"day_number": 4, "title": "In the days before your period", "notes": "Some women notice feeling hungrier or craving richer, sweeter foods in the days before their period, though this varies considerably between people and cycles — research finds a higher average energy intake in this phase, not a rule every mother will experience. Eating enough through the day, rather than restricting and then giving in, tends to make those cravings easier to meet without distress.", "breakfast_a": "Oats porridge with banana and roasted almonds", "breakfast_b": "Egg-and-cheese toast", "lunch_a": "Rice with a chana masala and a cooked vegetable", "lunch_b": "Chicken-and-onion curry with roti and a cooked vegetable", "nourishment_break_a": "Dark chocolate with roasted almonds (adult portion — keep whole almonds out of the baby''s reach)", "nourishment_break_b": "Curd with a spoon of ground flaxseed", "dinner_a": "Roti with a lobia curry and a sautéed vegetable", "dinner_b": "Paneer-and-spinach curry with rice", "still_hungry": "A slice of banana bread"}, {"day_number": 5, "title": "Steady habits over strict syncing", "notes": "You may come across meal plans built entirely around your cycle''s phases. The underlying idea that hormones affect appetite is reasonable, but rigid phase-by-phase eating rules aren''t well supported by evidence. Regular meals with enough protein, fat, fibre and key minerals serve most cycle-related needs better than a strict schedule.", "breakfast_a": "Vegetable dalia with roasted walnuts and curd", "breakfast_b": "Egg bhurji with jowar roti", "lunch_a": "Rice with a moong dal and a leafy green vegetable", "lunch_b": "Prawn-and-drumstick curry with rice and a cooked vegetable", "nourishment_break_a": "Seasonal fruit with roasted sunflower seeds (adult portion — keep whole seeds out of the baby''s reach)", "nourishment_break_b": "Buttermilk with a spoon of roasted sesame seeds", "dinner_a": "Roti with a matki curry and a cooked vegetable", "dinner_b": "Chicken-and-tomato curry with rice and a cooked vegetable", "still_hungry": "A glass of milk with a few dates"}, {"day_number": 6, "title": "If cramps or heavy flow make eating harder", "notes": "Cramping, nausea or low appetite around your period can make regular meals feel like more effort than usual. Smaller, simpler meals eaten more often, warm foods and fluids, and not forcing a full plate when you feel unwell are all reasonable adjustments — they don''t undo anything about how you''ve been eating the rest of the month. Worth knowing: Bleeding through one or more pads or tampons every hour for several hours, feeling faint or markedly dizzy, experiencing severe or worsening pain, or having difficulty staying upright requires urgent medical assessment. Bleeding lasting more than seven days, repeated large clots, increasing fatigue or a major change from your previous pattern should also be discussed promptly with your healthcare provider.", "breakfast_a": "Vegetable khichdi with curd", "breakfast_b": "Boiled egg with vegetable toast", "lunch_a": "Rice with a moong dal and a cooked vegetable", "lunch_b": "A hearty chicken-and-vegetable soup with rice", "nourishment_break_a": "Warm milk with a pinch of turmeric", "nourishment_break_b": "Roasted makhana with a banana (adult portion — keep whole makhana out of the baby''s reach)", "dinner_a": "Khichdi with ghee and a cooked vegetable", "dinner_b": "Egg curry with rice and a sautéed vegetable", "still_hungry": "A few plain crackers with warm milk"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Has anything about your appetite, energy or cravings shifted since your cycle changed this year — and have you been treating that shift as information, or as something to fight?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to meet a hungrier week with more food instead of less — trusting that your appetite knows something useful, even when it''s inconvenient?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: regular, adequate meals serve you better than rules built around any single number on a calendar or a scale.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 55: Eating well as your toddler starts daycare
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   55,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well as your toddler starts daycare',
   '"A new routine doesn''t leave less room for your own meals — it just asks you to protect them differently."',
   'Starting daycare or preschool is a big routine shift — new drop-off and pickup windows, a toddler who may be more tired or clingy at home, and a schedule that takes weeks to settle. Your own regular meals can quietly get crowded out during that adjustment if you''re not deliberate about protecting them. Children commonly experience more respiratory and stomach infections during their first year in group childcare because they are being exposed to many unfamiliar germs. The frequency often begins to fall during the second year of attendance, although every child and childcare setting is different. This is a common adjustment pattern and not, by itself, evidence that the childcare choice is wrong. Parents and other household members may also catch some of these infections through close contact at home. Frequent mild illnesses during this transition do not automatically mean that a parent''s underlying health has deteriorated, although persistent, unusually severe or recurrent infections deserve medical assessment. No single food or routine supplement is proven to prevent the ordinary run of daycare infections or make them disappear immediately. Handwashing, appropriate exclusion when ill and staying current with recommended vaccinations remain central. Food''s practical role is supporting adequate energy, protein and fluids — not acting as an instant "immunity booster." It''s reasonable for meals to get simpler during the adjustment weeks. A new routine is allowed to feel logistically harder before it feels easier, and that includes your own food, not just the household schedule.',
   'If you keep catching your toddler''s colds or stomach bugs: that''s common in the first year of group childcare and often eases in the second — food''s role is supporting adequate energy, protein and fluids while you''re unwell, not acting as an immunity booster. Use a condition-specific supplement only when your care team has clinically indicated it, not as a routine daycare precaution. If a chronic condition you manage tends to flare with disrupted sleep or new stress: a demanding transition like this one can be a trigger — mention any increase in symptoms to your care team rather than assuming it''s simply the cost of the adjustment. If you''re newly pregnant or still breastfeeding while managing this transition: regular meals matter especially now — try not to let a rushed morning turn into a skipped one, even on the days that feel most chaotic. However smoothly or roughly this transition is going, it''s temporary — and feeding yourself properly through it isn''t one more task competing for your attention, it''s part of how you get through it.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "A new daycare or preschool routine can reshuffle everything — mornings, moods, energy, appetite. It''s allowed to feel like an adjustment for weeks, and your own meals don''t have to wait until things settle down to matter.", "breakfast_a": "Vegetable poha with peanuts", "breakfast_b": "Egg-and-tomato omelette with toast", "lunch_a": "Rice with a toor-moong dal and a cooked vegetable", "lunch_b": "Chicken curry with rice and a leafy green vegetable", "nourishment_break_a": "Seasonal fruit with roasted almonds (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Buttermilk with roasted cumin and roasted chana (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "dinner_a": "Roti with a masoor-moong dal and a cooked vegetable", "dinner_b": "Fish curry with roti and a leafy green vegetable", "still_hungry": "A boiled egg"}, {"day_number": 2, "title": "The first few weeks of drop-off", "notes": "Early mornings can get tighter once drop-off enters the picture, and it''s easy to let your own breakfast shrink to whatever''s fastest or skip it while managing a clingy toddler. A meal that takes five minutes still counts as a real one — it doesn''t need to be elaborate to matter.", "breakfast_a": "Vegetable-stuffed paratha with curd", "breakfast_b": "Boiled eggs with a banana", "lunch_a": "Rice with a chana curry and a sautéed vegetable", "lunch_b": "Egg-and-potato curry with roti and a cooked vegetable", "nourishment_break_a": "Roasted chana with an apple (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Dates with a glass of milk", "dinner_a": "Roti with a rajma-vegetable curry", "dinner_b": "Mutton-and-onion curry with rice and a cooked vegetable", "still_hungry": "Plain crackers with curd or milk"}, {"day_number": 3, "title": "When you catch what they bring home", "notes": "Children commonly experience more respiratory and stomach infections during their first year in group childcare, because they''re being exposed to many unfamiliar germs — a pattern that often begins to ease during the second year, though every child and setting differs. Parents and other household members may also catch some of these infections through close contact at home. It isn''t, by itself, a sign the choice was wrong. Worth knowing: During vomiting or diarrhoea, small frequent sips may be easier than a full glass. Use an oral rehydration solution when advised or when fluid losses are significant; sugary drinks and homemade \"immune\" mixtures are not substitutes for appropriate rehydration or medical care.", "breakfast_a": "Vegetable dalia with curd", "breakfast_b": "Soft scrambled eggs with toast", "lunch_a": "Soft vegetable-moong dal khichdi with ghee", "lunch_b": "Chicken-and-vegetable soup with rice", "nourishment_break_a": "Warm lemon water with honey and toast or plain crackers (honey may soothe the throat but does not treat the infection)", "nourishment_break_b": "Toast with mashed banana and a small bowl of curd, if tolerated", "dinner_a": "Moong dal soup with rice and a soft cooked vegetable", "dinner_b": "Egg curry with soft rice and a soft cooked vegetable", "still_hungry": "A small bowl of curd or warm milk, if tolerated"}, {"day_number": 4, "title": "When the whole house is passing something back and forth", "notes": "Some stretches, it can feel like one cold hands off to the next before anyone fully recovers. No single food or supplement is proven to break that cycle faster — handwashing, keeping a sick child home when advised, and staying current on vaccinations remain central. Food''s practical role is supporting adequate energy, protein and fluids for whoever''s under the weather, not acting as an instant immunity booster. Worth knowing: Difficulty breathing, unusual drowsiness or reduced responsiveness, inability to keep fluids down, signs of dehydration, severe weakness, or rapidly worsening symptoms require urgent medical advice. For a child, follow their paediatrician''s guidance about fever because urgency depends on age, temperature, duration and accompanying symptoms. Persistent fever, repeated vomiting or symptoms that are not improving should be medically reviewed.", "breakfast_a": "Vegetable upma with roasted peanuts", "breakfast_b": "Egg-and-spinach toast", "lunch_a": "Rice with a lauki-moong dal and a cooked vegetable", "lunch_b": "Chicken-and-vegetable curry with rice", "nourishment_break_a": "Guava with roasted walnuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Curd with a spoon of ground roasted flaxseed", "dinner_a": "Roti with a moong-methi dal and a sautéed vegetable", "dinner_b": "Fish curry with rice and a leafy green vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "New windows, new meals", "notes": "If your old meal timings no longer fit around a new drop-off-and-pickup schedule, the timings are allowed to move. Batch-cooking a dal or curry that reheats well, or keeping simple protein options on hand, can make it easier to eat properly even on the days that feel most rushed.", "breakfast_a": "Ragi porridge prepared with milk or fortified plant drink, with roasted almonds; jaggery optional", "breakfast_b": "Egg bhurji with multigrain toast", "lunch_a": "Rice with a chana-tomato masala and a cooked vegetable", "lunch_b": "Prawn-and-vegetable curry with rice", "nourishment_break_a": "Roasted makhana with a guava (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Buttermilk with roasted sesame seeds", "dinner_a": "Roti with matki-tomato curry and a cooked vegetable", "dinner_b": "Paneer-and-capsicum curry with rice", "still_hungry": "A banana"}, {"day_number": 6, "title": "If guilt shows up", "notes": "Guilt about leaving your toddler at daycare, or relief that you have a few hours back, can both show up in the same week — sometimes the same afternoon. Neither one needs to be resolved before you feed yourself properly; a hard morning doesn''t cancel your right to a real lunch.", "breakfast_a": "Moong dal cheela with tomato chutney", "breakfast_b": "Egg-and-onion bhurji with toast", "lunch_a": "Rice with a rajma curry and a leafy green vegetable", "lunch_b": "Mutton-and-vegetable curry with roti", "nourishment_break_a": "Dates with roasted peanuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Curd with a spoon of soaked chia seeds", "dinner_a": "Roti with a green-moong dal and a cooked vegetable", "dinner_b": "Chicken tikka with roti and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. What''s one part of your own routine — a meal, a break, a habit — that''s gotten smaller since this transition started, and is there a simple way to give it a bit of room back?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat a rushed, imperfect week as reason to feed yourself more carefully, rather than less?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: a demanding season is exactly when regular, adequate meals matter most, not a time to let them slide.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 56: Eating well when your toddler becomes a picky eater
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   56,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when your toddler becomes a picky eater',
   '"Your child''s plate doesn''t need to be resolved before your own meal is worth finishing."',
   'Somewhere between one and three years old, many toddlers become far more selective about food than they were as babies — favouring a short list of foods, refusing anything new, or rejecting a food they happily ate last week. It''s one of the most common stages in early childhood eating, and it usually eases with time. A young child may need eight to ten exposures—or sometimes many more—before becoming willing to try a new food. An exposure can simply mean seeing, touching, smelling or tasting it without pressure. The number is not a deadline, and one refusal is not a final answer. One commonly used responsive-feeding framework gives the caregiver responsibility for what is offered and when and where meals happen, while the child decides whether to eat and how much. It is a practical framework rather than a test of perfect parenting, and it should be adapted when a child has medical, developmental, sensory or feeding needs. Pressure, bribery and repeatedly replacing the entire meal after a refusal can increase stress and negotiation. A more balanced approach is to offer the family meal with at least one familiar food the child generally accepts, without requiring them to taste or finish anything. This week keeps that same boundary in view for your own eating. A toddler''s refusal is a normal, temporary phase to manage calmly — it isn''t a problem for you to solve by skipping your own meal, restricting your own diet, or treating a hard mealtime as something to get through before you''re allowed to eat properly yourself.',
   'If your child has a diagnosed feeding disorder, allergy, or is followed by a feeding therapist, allergist or paediatric GI specialist: continue their individualised plan exactly — this week''s general guidance is for ordinary picky eating and doesn''t override a clinician''s specific instructions. If you''re being advised to eliminate major food groups from the family''s shared meals without a clinical diagnosis behind it: that isn''t established guidance for ordinary picky eating — it''s worth checking with your child''s paediatrician before restricting what the rest of the household, including you, eats. If you''re newly pregnant or still breastfeeding while managing this stage: your own protein and energy needs haven''t shrunk because mealtimes have gotten harder — protect your plate the same way you would any other week. A difficult mealtime is common, temporary, and rarely about anything you did wrong — and feeding yourself properly through it isn''t a reward you earn after theirs goes smoothly.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Most toddlers go through a phase of eating a narrower range of foods, sometimes dramatically, often somewhere between one and three years old. It tends to ease with time on its own, and it isn''t a verdict on your cooking, your effort or how well you''re doing this.", "breakfast_a": "Besan chilla with a tomato-onion salad", "breakfast_b": "Boiled eggs with whole-wheat toast and cucumber", "lunch_a": "Rice with an urad-moong dal and a bhindi sabzi", "lunch_b": "Chicken curry with rice and a cauliflower sabzi", "nourishment_break_a": "Roasted chana with a pear (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Buttermilk with roasted cumin and roasted chana (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "dinner_a": "Roti with a sabut moong dal and a green beans sabzi", "dinner_b": "Paneer curry with roti and a carrot-peas sabzi", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 2, "title": "The plate that isn''t a negotiation", "notes": "A widely used approach to feeding puts the caregiver in charge of what food is offered, and when and where it''s eaten — while the child decides whether to eat it, and how much. Keeping these roles reasonably consistent can reduce pressure and repeated bargaining, while still allowing flexibility for the child''s age, needs and family circumstances. That same calm division is worth applying to your own plate too: your meal doesn''t need their cooperation to count as finished.", "breakfast_a": "Vegetable idli with sambar", "breakfast_b": "Egg-and-capsicum toast", "lunch_a": "Rice with a masoor dal and a tinda sabzi", "lunch_b": "Fish curry with rice and a green beans sabzi", "nourishment_break_a": "Roasted makhana with an orange (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Fully cooked sprouted-moong chaat with lemon", "dinner_a": "Roti with chana-methi curry and a cooked vegetable", "dinner_b": "Mutton curry with roti and a cauliflower sabzi", "still_hungry": "A banana"}, {"day_number": 3, "title": "When mealtimes turn into a battle", "notes": "Pleading, bribing with dessert, or repeatedly cooking an entirely different dish after a refusal are common instincts, but they tend to make refusal more entrenched over time rather than less — and they often cost you your own meal in the process, eaten cold, standing at the counter, or not at all. Offering the family meal alongside one food your child generally accepts, without requiring a taste or a finished plate, tends to work better than swapping the whole meal. A calmer, less negotiated mealtime is worth building toward — for both of you — but it''s a gradual shift, not a switch to flip tonight.", "breakfast_a": "Curd rice with pomegranate", "breakfast_b": "Moong dal cheela with coriander chutney", "lunch_a": "Rice with a kabuli chana curry and a capsicum sabzi", "lunch_b": "Prawn curry with rice and a green beans sabzi", "nourishment_break_a": "A pear with roasted walnuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Buttermilk with roasted fennel seeds", "dinner_a": "Roti with lobia-tomato curry and a cooked vegetable", "dinner_b": "Chicken-and-methi curry with roti and a cooked vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 4, "title": "If someone suggests cutting things from your own diet too", "notes": "A fussy toddler often invites advice — including suggestions to remove dairy, gluten or entire food groups from the family''s meals in the hope that it fixes the refusal. Without a clinical diagnosis behind it, that isn''t an established way to resolve ordinary picky eating, and it doesn''t need to reshape your own plate. Worth knowing: Restrictive \"anti-picky-eating\" diets marketed to parents — cutting out entire food groups without a diagnosis — aren''t supported by paediatric feeding guidance and can add stress to mealtimes without resolving the refusal. If this applies to you (a doctor has diagnosed a food allergy or intolerance in your child): follow the elimination and—where clinically appropriate—supervised reintroduction plan provided by their qualified healthcare professional. Do not attempt reintroduction at home when the allergy plan advises otherwise. This doesn''t automatically mean removing the same food from your own diet — do that only if your own clinician advises it.", "breakfast_a": "Oats-vegetable uttapam with sambar or curd", "breakfast_b": "Egg bhurji with whole-wheat toast", "lunch_a": "Rice with a mild dal makhani and a cauliflower sabzi", "lunch_b": "Paneer curry with rice and a green beans sabzi", "nourishment_break_a": "Roasted peanuts with a guava (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Curd with ground roasted flaxseed", "dinner_a": "Roti with a masoor-arhar dal and a bhindi sabzi", "dinner_b": "Chicken curry with roti and a capsicum sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 5, "title": "Family meals, imperfect and shared", "notes": "Eating together — even a simple, repeated meal, without screens, without pressure to finish — remains one of the more consistently useful habits during a picky phase. It doesn''t have to be elaborate, and it isn''t only for your toddler''s benefit: a shared table is also where your own meal gets protected.", "breakfast_a": "Ragi dosa with coconut chutney and sambar or curd", "breakfast_b": "Egg-and-mushroom toast", "lunch_a": "Rice with an arhar dal and a lauki sabzi", "lunch_b": "Mutton curry with rice and a green beans sabzi", "nourishment_break_a": "Roasted almonds with a banana (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of milk with a few soaked raisins", "dinner_a": "Roti with a chana-spinach curry", "dinner_b": "Fish curry with roti and a cauliflower sabzi", "still_hungry": "A few plain crackers with curd"}, {"day_number": 6, "title": "If you''re genuinely worried", "notes": "Most picky phases resolve on their own without any special intervention. But it''s worth checking in with your pediatrician — rather than waiting to see if it passes — if your child is losing weight, gaining much less than expected, or has visibly dropped off their usual growth curve. Worth knowing: Growth is assessed over time using a growth chart, not diagnosed at home from one difficult week. Seek professional guidance if your child is losing weight or not growing as expected; regularly coughs, chokes or gags while eating; frequently vomits; holds food in the mouth; has difficulty chewing age-appropriate textures; takes unusually long to finish meals; appears distressed or in pain when eating; or has a diet so restricted that nutrition or hydration may be affected. Sudden choking, difficulty breathing or suspected food aspiration requires urgent help.", "breakfast_a": "Sooji upma with mixed vegetables and curd", "breakfast_b": "Egg-and-onion omelette with whole-wheat toast", "lunch_a": "Rice with a moong-chana dal and a carrot-peas sabzi", "lunch_b": "Chicken-and-tomato curry with rice and a bhindi sabzi", "nourishment_break_a": "Buttermilk with roasted chana", "nourishment_break_b": "A pear with roasted sesame seeds", "dinner_a": "Roti with a rajma-spinach curry", "dinner_b": "Paneer curry with roti and a lauki sabzi", "still_hungry": "A glass of warm milk with a pinch of turmeric"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Is there a mealtime habit — pleading, bribing, cooking a separate dish, or skipping your own plate to manage theirs — that''s crept in, and would it help to name it out loud rather than just push through it?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat your child''s refusal as information about this phase, rather than as something urgent for you to fix tonight?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: your own meals stay worth protecting, whatever else is unsettled around them.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 57: Eating well through a postpartum thyroid swing
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   57,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well through a postpartum thyroid swing',
   '"Persistent fatigue, anxiety or unexplained weight change deserves a thyroid check — not just more willpower or a stricter diet."',
   'Postpartum thyroiditis usually begins during the first year after birth, but its underactive phase—and the symptoms associated with it—may continue beyond the first birthday. A new or persistent thyroid symptom at this stage still deserves medical assessment, but it should not automatically be assumed to be postpartum thyroiditis. Postpartum thyroiditis is an autoimmune inflammation of the thyroid that affects approximately 5–10% of women during the first year after birth, with risk being higher in women who have type 1 diabetes, thyroid antibodies, or a personal or family history of autoimmune thyroid disease. It can bring an overactive phase, an underactive phase, both in sequence, or neither. An overactive phase, when it happens, tends to appear in the first few months after birth: a racing heart, anxiety, poor sleep, appetite or weight changes, and irritability. An underactive phase can follow it, or appear on its own, and can last the better part of a year: fatigue, weight gain, constipation, dry skin and low mood. Because these symptoms overlap with ordinary postpartum exhaustion, mood changes and stress, symptoms alone cannot confirm the cause. A clinician can assess the full picture and use thyroid blood tests—commonly including TSH and free T4—to investigate it. Most people''s thyroid function settles back to normal within twelve to eighteen months, though a meaningful share go on to need longer-term thyroid hormone treatment. None of this reflects anything you did or didn''t do, and it isn''t something a diet, cleanse or supplement fixes on its own. Food''s role here is steady support — regular, adequate meals while this settles — not an attempt to self-treat symptoms through iodine-heavy foods, kelp, or thyroid "support" products.',
   'If you''ve been diagnosed with postpartum thyroiditis, hypothyroidism or hyperthyroidism: continue your doctor''s monitoring and any prescribed medication exactly — food supports you through this, but it doesn''t replace thyroid hormone treatment when that''s needed. If you have a pre-existing thyroid condition, such as Hashimoto''s or Graves'', or known thyroid antibodies: the postpartum period carries a meaningfully higher chance of a flare or shift — keep up with your usual follow-up rather than assuming things have stayed stable. If you''re trying to conceive again or newly pregnant while your thyroid is still settling: ask for a TSH check before or as soon as you conceive, since thyroid balance is assessed differently in a new pregnancy. If you also manage diabetes, PCOS, high blood pressure, kidney disease, anaemia, food allergies or another condition: use the meal choices and portions recommended for you by your healthcare team. This general weekly plan should not override an individual treatment plan. Thyroid symptoms can persist beyond the first postpartum year, and other thyroid conditions can also appear at this stage. Either way, they are medical concerns—not a reflection of how well you have eaten or cared for yourself.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Postpartum thyroiditis usually begins within the first year after delivery, but its effects may continue beyond it. If you have recently entered your child''s second year and still feel unmistakably \"off,\" take that seriously rather than assuming it is ordinary tiredness.", "breakfast_a": "Moong dal dosa with tomato chutney", "breakfast_b": "Egg-and-carrot toast", "lunch_a": "Rice with a matki dal and a cabbage sabzi", "lunch_b": "Fish curry with rice and a bhindi sabzi", "nourishment_break_a": "Roasted walnuts with a banana (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of buttermilk with a small bowl of roasted chana", "dinner_a": "Roti with a chana-lauki curry", "dinner_b": "Minced chicken with peas and roti", "still_hungry": "A boiled egg"}, {"day_number": 2, "title": "When it feels like restlessness, not recovery", "notes": "An overactive phase can follow birth in some women — a racing heart, anxiety, trouble sleeping, unexpected weight loss despite eating normally, or a new edge of irritability. It usually shows up in the first few months after delivery and is easy to mistake for ordinary new-parent stress. Worth knowing: These symptoms are commonly written off as stress or anxiety, but symptoms alone cannot identify the cause. A clinician can assess them and order thyroid blood tests when appropriate. If palpitations, unexplained weight loss or persistent anxiety are new and lasting, it''s worth mentioning to your doctor rather than assuming it will pass on its own. Seek urgent medical care for chest pain, fainting, severe breathlessness, confusion, or a very fast or irregular heartbeat that does not settle. These symptoms should not be managed through food changes alone.", "breakfast_a": "Vegetable-stuffed roti with curd", "breakfast_b": "Boiled eggs with one slice of whole-grain toast and a guava", "lunch_a": "Rice with a toor dal and a capsicum sabzi", "lunch_b": "Paneer curry with rice and a cabbage sabzi", "nourishment_break_a": "Roasted chana with an orange (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A banana with a glass of milk", "dinner_a": "Roti with a rajma-tomato curry", "dinner_b": "Mutton curry with rice and a bhindi sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "When it feels like exhaustion food alone can''t fix", "notes": "An underactive phase can follow the restless one, or turn up on its own — fatigue, weight gain, constipation, dry skin, low mood and poor exercise tolerance, often several months after birth, sometimes lasting the better part of a year. Worth knowing: This phase can look a lot like ordinary depletion. If the symptoms are persistent or affecting daily life, a clinician can assess whether thyroid dysfunction or another medical concern may be contributing. Persistent low mood alongside these physical symptoms is worth raising with your doctor — it isn''t something to push through with willpower or a stricter diet.", "breakfast_a": "Ragi porridge with milk and roasted walnuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "breakfast_b": "Egg-and-spinach bhurji with toast", "lunch_a": "Rice with a moong-lauki dal and a cooked vegetable", "lunch_b": "Chicken-and-spinach curry with rice and a cooked vegetable", "nourishment_break_a": "Curd with a spoon of roasted sesame seeds", "nourishment_break_b": "A pear with roasted peanuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "dinner_a": "Roti with a masoor dal and a cooked vegetable", "dinner_b": "Fish curry with roti and a cooked vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 4, "title": "If you''ve been prescribed thyroid medicine", "notes": "If you take levothyroxine, it is commonly taken with plain water on an empty stomach, usually 30–60 minutes before breakfast, or at bedtime several hours after the last meal. Calcium and iron supplements can reduce its absorption and are generally kept at least four hours apart. Follow the exact instructions given with your prescription, because your clinician may recommend a different routine. If this applies to you (you take thyroid medicine): take your medicine at a consistent time, and tell your doctor or pharmacist about calcium, iron, antacids, multivitamins and other supplements. Do not change the dose or timing on your own. If you take a thyroid medicine other than levothyroxine, follow the instructions specific to that medicine.", "breakfast_a": "Oats idli with sambar", "breakfast_b": "Egg-and-tomato bhurji with toast", "lunch_a": "Rice with a chana dal and a capsicum sabzi", "lunch_b": "Paneer curry with rice and a bhindi sabzi", "nourishment_break_a": "Curd with a spoon of soaked sabja seeds", "nourishment_break_b": "Roasted makhana with a pear; serve age-appropriately if sharing with a young child", "dinner_a": "Roti with an urad dal and a cooked vegetable", "dinner_b": "Chicken curry with roti and a cooked vegetable", "still_hungry": "A few plain crackers with curd"}, {"day_number": 5, "title": "If someone suggests iodine or a thyroid \"support\" product", "notes": "More iodine is not automatically better. Kelp tablets, iodine drops, seaweed concentrates and some \"thyroid support\" blends can provide very large or unpredictable amounts and may worsen thyroid dysfunction in susceptible people. Continue using ordinary foods and iodized salt in normal dietary amounts unless your clinician advises differently, but do not begin a concentrated iodine or kelp product to treat thyroid symptoms yourself.", "breakfast_a": "Idli with coconut chutney and sambar", "breakfast_b": "Egg-and-onion toast", "lunch_a": "Rice with a rajma dal and a cauliflower sabzi", "lunch_b": "Fish with lemon rice and beans", "nourishment_break_a": "A guava with roasted chana", "nourishment_break_b": "A banana with plain curd and a spoon of ground sesame seeds", "dinner_a": "Roti with a green-gram dal and a cooked vegetable", "dinner_b": "Chicken curry with rice and a cooked vegetable", "still_hungry": "A banana"}, {"day_number": 6, "title": "If you''re thinking about another pregnancy while this settles", "notes": "Thyroid balance matters differently once you''re pregnant again, and having had postpartum thyroiditis once makes it considerably more likely to happen again after a future birth. If this applies to you (you''re trying to conceive again or newly pregnant and your thyroid function hasn''t been rechecked since birth): ask for a TSH check before or as soon as you conceive, especially if you had any thyroid symptoms or a diagnosis after this birth.", "breakfast_a": "Besan cheela with tomato chutney", "breakfast_b": "Egg-and-capsicum bhurji with toast", "lunch_a": "Rice with a moong dal and a cauliflower sabzi", "lunch_b": "Chicken-and-moong khichdi", "nourishment_break_a": "Roasted almonds with a guava (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of milk with one or two dates and a small handful of roasted chana", "dinner_a": "Roti with a rajma curry and a cooked vegetable", "dinner_b": "Paneer curry with roti and a cooked vegetable", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Have you noticed any of this week''s symptoms in yourself since giving birth, and if so, is there a conversation with your doctor you''ve been putting off?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat a stretch of unexplained fatigue or mood change as a medical question worth asking, rather than a personal failing to manage alone?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: your body''s signals are worth listening to, long after the earliest postpartum weeks have passed.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 58: Eating well when you're traveling with your family
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   58,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when you''re traveling with your family',
   '"A trip doesn''t have to mean choosing between your child''s routine and your own next meal."',
   'Travel disrupts routine for both of you, and food is often the first thing that gets left to improvisation — a skipped meal, whatever''s sold at a rest stop, or eating only what your child accepts and treating that as enough for you too. Away from a familiar kitchen, food safety usually comes down to two things: how fresh and thoroughly cooked the food is, and where the water came from. Where water or sanitation is uncertain, choose food that is freshly cooked and served steaming hot. Prefer fruit you can wash with safe water and peel yourself, and avoid raw salads or pre-cut produce when their washing and storage are unknown. Frequent handwashing matters just as much as what you choose to eat. Perishable packed foods need a dependable cold source. If they have remained unrefrigerated for an uncertain or prolonged period—especially in hot weather—choose a fresh alternative rather than trying to rescue them. A simple, portable routine protects both of you far more than trying to eat perfectly: a few familiar snacks packed in advance, a plan for safe water, and a loose sense of when you''ll next eat. None of this needs to be elaborate. A trip is exactly the kind of stretch where good enough and regular beats ideal but skipped.',
   'If you manage diabetes or another blood-sugar condition: travel schedules and unfamiliar food can shift glucose patterns more than usual — carry familiar snacks and your monitoring supplies, and keep your usual meal timing where you reasonably can. If you have a digestive condition such as IBS or IBD: travel is a common trigger for flares — carry safe, familiar foods and your usual management plan rather than assuming you''ll manage on whatever''s available. If you''re pregnant or breastfeeding while traveling: food and water precautions matter especially for you too — this week''s caution isn''t only about your child. A trip is temporary, and feeding yourself properly through it isn''t an indulgence you have to earn — it''s part of what keeps you upright enough to enjoy any of it.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Travel unsettles routine for everyone in the family, and food is often the first thing left to chance — a skipped meal, whatever''s available at a rest stop, or eating only what your child will accept and calling it done for both of you. Travel fallback: A whole fruit with roasted chana, plus sealed milk or curd kept safely chilled.", "breakfast_a": "Vegetable poha with roasted peanuts", "breakfast_b": "Egg-and-potato toast", "lunch_a": "Rice with a toor-arhar dal and a beans sabzi", "lunch_b": "Chicken curry with rice and a beans sabzi", "nourishment_break_a": "Roasted peanuts with a banana (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of buttermilk with roasted jeera and a small bowl of roasted chana", "dinner_a": "Roti with a moong dal and a beans sabzi", "dinner_b": "Paneer curry with roti and a beans sabzi", "still_hungry": "A banana"}, {"day_number": 2, "title": "Packing for two, not just one", "notes": "Most travel packing lists are built entirely around the child — snacks, spare clothes, a favourite toy — while the adult''s own meals are left to whatever turns up. Packing a few familiar things for yourself too, not only for your child, makes it far more likely you''ll actually eat on a long travel day. Travel fallback: A homemade vegetable or fully cooked egg roll, eaten promptly or kept reliably chilled in an insulated bag with ice packs.", "breakfast_a": "Wheat dalia with grated jaggery and milk", "breakfast_b": "Egg-and-cucumber sandwich", "lunch_a": "Rice with a rajma-carrot curry", "lunch_b": "Fish curry with rice and a carrot sabzi", "nourishment_break_a": "Roasted chana with a mandarin (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of milk with a banana", "dinner_a": "Roti with a chana-tomato curry and a beans sabzi", "dinner_b": "Mutton curry with rice and a carrot sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "Food and water, away from your own kitchen", "notes": "Away from home, the biggest food-safety differences usually come down to two things: how fresh and thoroughly cooked the food is, and where the water came from — for drinking, for washing produce, and for anything your child is given. Worth knowing: Where water or sanitation is uncertain, choose food that has been freshly cooked and served steaming hot, and use factory-sealed, boiled or appropriately treated water. Prefer fruit you can wash with safe water and peel yourself. Avoid raw salads, pre-cut fruit and food left unrefrigerated when their preparation or storage is uncertain. Wash your hands with soap and safe water when available; otherwise, use an alcohol-based hand sanitiser containing at least 60% alcohol. Travel fallback: Freshly cooked, steaming-hot dal-rice or idli-sambar from a reliable food outlet.", "breakfast_a": "Rava idli with tomato chutney", "breakfast_b": "Egg-and-spinach omelette with toast", "lunch_a": "Rice with a masoor-toor dal and a cooked vegetable", "lunch_b": "Chicken curry with rice and a capsicum sabzi", "nourishment_break_a": "A guava with roasted walnuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Buttermilk with roasted cumin and a banana", "dinner_a": "Roti with a moong-masoor dal and a cooked vegetable", "dinner_b": "Fish curry with roti and a capsicum sabzi", "still_hungry": "A glass of warm milk"}, {"day_number": 4, "title": "If your stomach turns on you mid-trip", "notes": "An upset stomach — yours or your child''s — is common enough while traveling that it''s worth having a plan before it happens, rather than figuring it out in the moment. Worth knowing: Pack commercially prepared oral rehydration salts—not an ordinary sports or electrolyte drink—and mix them with exactly the amount of boiled, treated or sealed safe water stated on the packet. ORS can help prevent or treat dehydration when diarrhoea or repeated vomiting causes fluid loss; continue breastfeeding and usual tolerated foods. Seek medical care promptly if a young child has markedly fewer wet nappies or trips to urinate, unusual sleepiness or irritability, a very dry mouth, persistent vomiting that prevents drinking, blood in the stool, or a high fever. Adults should seek care for severe dehydration, fainting, bloody diarrhoea, high fever, severe abdominal pain or symptoms that are worsening or not improving. If travelling to a destination with a higher risk of traveller''s diarrhoea, ask your child''s doctor before departure what symptoms would require treatment and where to seek care. Do not give a child antibiotics or anti-diarrhoeal medicine unless specifically advised. Travel fallback: ORS plus familiar, tolerated foods if illness occurs; do not force a restrictive menu.", "breakfast_a": "Vegetable dalia with curd", "breakfast_b": "Fully cooked boiled eggs with toast", "lunch_a": "Soft khichdi with ghee", "lunch_b": "Chicken-and-vegetable soup with rice, if tolerated", "nourishment_break_a": "Buttermilk with a pinch of salt and roasted cumin, in small sips", "nourishment_break_b": "Toast with mashed banana, if tolerated", "dinner_a": "Moong dal soup with rice and a soft cooked vegetable", "dinner_b": "Paneer bhurji with soft rice, if tolerated", "still_hungry": "A small bowl of curd or warm milk, if tolerated"}, {"day_number": 5, "title": "If you''re still nursing or preparing milk on the road", "notes": "Continuing to breastfeed while traveling is often simpler than it looks — it needs no water, no bottles, and no preparation, which can be one less thing to plan around on a travel day. If this applies to you (you''re pumping while traveling): wash your hands thoroughly with soap and safe water before pumping or handling expressed milk. If soap and safe water are not available, use an alcohol-based hand sanitiser containing at least 60% alcohol. Clean parts that contact milk with safe water and dish soap in a clean basin—not directly in an unfamiliar sink—and allow them to air-dry completely. If you will not have access to safe water and proper cleaning facilities, carry additional clean pump sets to use until the used parts can be washed thoroughly. If this applies to you (you''re preparing infant formula while traveling): ready-to-feed liquid formula can be the simplest option when available because it is sterile until opened. For powdered formula, use a safe water source and follow the product label and applicable local health guidance exactly; bottled water is not necessarily sterile. Never dilute formula or add extra powder. Prepare feeds with clean equipment, cool them safely before feeding, and discard anything left after the recommended time. If this applies to you (your baby is under two months old, premature, or has a weakened immune system): ask the baby''s clinician about the safest preparation method before travelling; guidance may include mixing powdered formula with water that is still at least 70°C. Travel fallback: Shelf-stable ready-to-eat food for the mother, plus properly stored expressed milk or correctly prepared formula where applicable.", "breakfast_a": "Moong dal cheela with mint-coriander chutney", "breakfast_b": "Egg-and-onion bhurji with toast", "lunch_a": "Rice with a chana-lauki curry", "lunch_b": "Paneer curry with rice and a cooked vegetable", "nourishment_break_a": "Roasted makhana with an apple; serve age-appropriately if sharing with a young child", "nourishment_break_b": "A glass of milk with a few soaked almonds (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "dinner_a": "Roti with a rajma dal and a cooked vegetable", "dinner_b": "Mutton curry with roti and a cooked vegetable", "still_hungry": "A boiled egg"}, {"day_number": 6, "title": "If someone says just skip a meal, it''s only one day", "notes": "A packed itinerary makes it easy to hear — or tell yourself — that skipping a meal today doesn''t matter. Missing a meal occasionally is not a failure. But on a demanding travel day, having even a simple backup snack can protect your energy and make the next available meal feel more manageable. Travel fallback: Whole-grain crackers, fruit that can be peeled, roasted chana, or a sealed nut-butter portion for the adult.", "breakfast_a": "Besan chilla with a cooked vegetable filling", "breakfast_b": "Boiled eggs with whole-grain toast and a mandarin", "lunch_a": "Rice with a matki-moong dal and a cooked vegetable", "lunch_b": "Chicken-and-tomato curry with rice and a cooked vegetable", "nourishment_break_a": "A mandarin with roasted chana", "nourishment_break_b": "Curd with a spoon of chia seeds", "dinner_a": "Roti with a lobia dal and a cooked vegetable", "dinner_b": "Fish curry with rice and a cooked vegetable", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. What''s one small thing you could pack or plan ahead of your next trip that would make it easier to feed yourself properly, not just your child?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat your own meals as part of the travel plan, rather than whatever''s left over once everyone else is fed?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: a change in routine is not a reason to let your own meals slide.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 59: Eating well during festivals and celebrations
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   59,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well during festivals and celebrations',
   '"A festival plate can include the foods you love without turning into a diet you owe afterward."',
   'Festivals and celebrations bring food into a different register — abundance, tradition, generosity — and it''s common to treat that abundance as something to survive rather than enjoy, either by overeating past comfort or by white-knuckling restriction through every gathering. Enjoying festive food doesn''t require a plan to make up for it afterward. A day or two of richer, sweeter, more indulgent eating doesn''t undo months of regular meals, and it doesn''t need a stricter day to follow it. For anyone managing diabetes or another blood-sugar condition, festivals are also a common flashpoint — not because celebration itself is risky, but because meal timing, portion size and monitoring often slip on a busy, social day. A little extra planning protects you without requiring you to sit out the celebration. None of this is about permission or restriction. It''s about letting a festival be what it is — a full, human occasion — without treating your body as the thing that has to pay for it.',
   'If you manage diabetes or another blood-sugar condition: do not skip earlier meals to "save room" for festival food. Keep meals, medication and monitoring as close to your usual plan as reasonably possible, carry your usual treatment for low blood sugar, and use the monitoring schedule already recommended for you. If the celebration will substantially delay a meal, follow the adjustment plan given by your diabetes team rather than changing medication on your own. If you have a history of disordered eating or a difficult relationship with food: festive gatherings can genuinely be harder. It is reasonable to sit with a trusted person, prepare a neutral response to comments about food or bodies, step away from an uncomfortable conversation, or follow an existing support plan. You do not have to rely on willpower or manage the gathering alone. If you''re pregnant or breastfeeding: the usual caffeine and alcohol guidance still applies at a celebration, even when everyone around you is drinking or the day feels like an exception. A festival is one day, or a few, inside a much longer pattern of regular eating — it doesn''t need to be perfect, and it doesn''t need to be punished afterward either.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Festivals and celebrations bring food into a different register — abundance, tradition, generosity — and it''s common to treat that abundance as something to survive rather than enjoy, either by overeating past comfort or by white-knuckling restriction through every gathering. At the celebration: Choose the festive dishes that are meaningful to you. You can eat them alongside the rest of the meal, return for more if you are still hungry, or stop when you have had enough. There is no requirement to earn the food beforehand or correct for it afterward. Celebration choice: A favourite family sweet or savoury festival dish.", "breakfast_a": "Vegetable paratha with a bowl of curd", "breakfast_b": "Egg-and-mushroom omelette with toast", "lunch_a": "Rice with a toor dal and a cabbage sabzi", "lunch_b": "Chicken curry with rice and a cabbage sabzi", "nourishment_break_a": "Roasted almonds with an orange (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of buttermilk with roasted cumin and a small bowl of roasted chana", "dinner_a": "Roti with a chana dal and a cabbage sabzi", "dinner_b": "Paneer-peas curry with roti", "still_hungry": "A banana"}, {"day_number": 2, "title": "If diabetes or blood sugar swings are part of your festival", "notes": "Festivals are a common flashpoint for anyone managing diabetes or another blood-sugar condition — not because celebrating is risky, but because meal timing, portion size and monitoring often slip on a busy, social day. Worth knowing: Regular, reasonably spaced meals can make a festival day more predictable. Enjoy sweets as part of a meal or alongside foods containing protein or fibre if that suits your established diabetes plan. Stay hydrated, monitor according to your usual instructions, and continue movement that is normal and safe for you. None of this means sitting out the foods that make the occasion meaningful. Celebration choice: If managing blood sugar, include the festive food in the meal pattern that normally works for you.", "breakfast_a": "Moong dal chilla with mint chutney", "breakfast_b": "Egg bhurji with toast", "lunch_a": "Rice with a masoor dal and a capsicum sabzi", "lunch_b": "Fish curry with rice and a capsicum sabzi", "nourishment_break_a": "Roasted chana with a guava", "nourishment_break_b": "Buttermilk with roasted ajwain and a banana", "dinner_a": "Roti with a lauki-chana curry", "dinner_b": "Chicken kofta curry with rice and beans", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "When sweets are pressed on you", "notes": "\"Just one more,\" \"you''ve barely eaten anything\" — festive hospitality often comes with pressure to keep taking second and third helpings. A full plate of festival food is already a full plate. Declining more isn''t a rejection of the person offering, and you don''t owe anyone proof of how much you enjoyed the day. Celebration choice: Accept the amount you genuinely want; declining another serving does not reject the person offering it.", "breakfast_a": "Idli with sambar and tomato chutney", "breakfast_b": "Egg-and-capsicum omelette with toast", "lunch_a": "Rice with a rajma dal and a cooked vegetable", "lunch_b": "Prawn curry with rice and a cooked vegetable", "nourishment_break_a": "A pear with roasted walnuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Curd with a spoon of roasted flaxseed", "dinner_a": "Roti with a moong-methi dal and a cooked vegetable", "dinner_b": "Mutton-and-spinach curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "The morning after", "notes": "The day after a celebration is just an ordinary day again. It doesn''t need a stricter menu, a skipped meal, or a \"detox\" to make up for what you ate — regular, adequate meals pick back up where they left off, without punishment attached.", "breakfast_a": "Vegetable upma with roasted peanuts", "breakfast_b": "Boiled eggs with whole-grain toast and a banana", "lunch_a": "Rice with a toor-masoor dal and a cooked vegetable", "lunch_b": "Paneer-and-tomato curry with roti", "nourishment_break_a": "A guava with roasted peanuts", "nourishment_break_b": "A glass of milk with soft fruit for the adult; if sharing with the toddler, prepare the fruit in an age-appropriate texture", "dinner_a": "Roti with a rajma-spinach curry", "dinner_b": "Egg curry with rice and a cooked vegetable", "still_hungry": "A boiled egg"}, {"day_number": 5, "title": "Your toddler''s first real festival plate", "notes": "This may be your child''s first festival old enough to notice and reach for the sweets everyone else is eating. Feeding guidance generally recommends avoiding added sugars before age two, but that does not need to become fear, shame or a family argument. If your child is offered or has a small taste, there is nothing to \"undo\" afterward. Return to the child''s usual meals and keep highly sweetened foods occasional rather than routine. Worth knowing: Many traditional sweets and festival snacks contain whole or chopped nuts, hard dried fruit, seeds, popcorn-like textures, or sticky and chewy fillings that can be choking hazards for young children. Breaking a hard or sticky sweet into a smaller piece may not make it safe. Choose a soft, age-appropriate food without hard pieces; nuts can be finely ground or offered as a smooth, thinly spread paste when already safely introduced. Seat your child upright and supervise closely while they eat.", "breakfast_a": "Besan chilla with finely chopped or softly cooked cucumber for the child; the adult may have cucumber salad", "breakfast_b": "Egg-and-mushroom bhurji with toast", "lunch_a": "Rice with a chana-tomato dal and a cooked vegetable", "lunch_b": "Chicken-and-tomato curry with roti and a cooked vegetable", "nourishment_break_a": "A banana with plain curd and finely ground makhana powder; keep whole roasted makhana in the adult portion only", "nourishment_break_b": "A glass of milk with smooth cashew paste spread thinly on soft toast, if cashew has already been safely introduced", "dinner_a": "Roti with a green-moong dal and a cooked vegetable", "dinner_b": "Paneer-and-capsicum curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "If alcohol is part of your celebration", "notes": "Weddings, New Year''s, a festival night out — celebrations often come with alcohol on the table, and it''s easy to feel like the exception should apply to you too. If this applies to you (alcohol is part of your celebration and you''re breastfeeding or could be pregnant): if you''re breastfeeding and choose to drink, allow at least two hours per standard drink before feeding, and make sure a sober adult is on hand. If you''re pregnant or could be, no amount of alcohol is known to be safe — an alcohol-free 0.0% drink for the toast can still make the occasion feel celebratory. If your child needs to feed before that waiting period has passed, previously expressed milk can be used if available. Pumping and discarding milk does not make alcohol leave the milk faster; alcohol levels fall as they fall in the bloodstream.", "breakfast_a": "Oats upma with mixed vegetables", "breakfast_b": "Boiled eggs with whole-grain toast and a guava", "lunch_a": "Rice with a chana-spinach dal and a cooked vegetable", "lunch_b": "Chicken-and-capsicum curry with rice and a cooked vegetable", "nourishment_break_a": "A mandarin with roasted peanuts", "nourishment_break_b": "Curd with a spoon of roasted pumpkin seeds", "dinner_a": "Roti with a masoor-chana dal and a cooked vegetable", "dinner_b": "Fish tikka with roti and a cooked vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Is there a festival or celebration coming up where you could try letting yourself simply enjoy the food, without a plan to earn it beforehand or make up for it after?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let a celebration be fully enjoyable, without treating your next meal as a correction for it?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: an occasion worth celebrating is not one that needs to be paid for afterward.')
