-- postpartum week 60: Eating well when your child is sick
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   60,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when your child is sick',
   '"Your child''s appetite is allowed to shrink today — yours still needs feeding, especially today."',
   'A sick child changes the shape of a day fast — a fever spikes, appetite disappears, sleep gets thin, and everyone''s plans narrow down to getting through the next few hours. It''s common for your own meals to be the first thing that quietly stops happening. A child''s appetite naturally drops during illness, and that''s usually not a sign of anything going wrong on its own. Fluids matter more than food volume in the short term, and appetite typically returns as the illness resolves. The traditional BRAT diet — banana, rice, applesauce and toast — is no longer recommended as an exclusive recovery diet because it provides too little protein, fat and overall nutritional variety. During diarrhoea, breastfeeding and appropriate fluids should continue, and familiar age-appropriate foods can be offered as tolerated. None of this works if you stop eating too. A day spent holding a feverish child, tracking symptoms and managing a smaller appetite than usual is still a full day of your own energy being spent — and it deserves real food, even in small, simple pieces. This week contains brief guidance about supporting a sick child, but the daily meal choices remain the mother''s meals. Any food or fluid suggested specifically for the child will be clearly labelled. Your child''s illness does not mean that you should follow a restricted recovery diet too.',
   'If your child has a chronic condition such as asthma, a seizure disorder, or a heart or kidney condition: illness can affect these differently, and your child''s usual care team is the right guide for symptom thresholds specific to that condition. If you are also unwell while caring for a sick child: your own hydration, food and rest still matter, and it''s reasonable to ask someone else to take a shift so you can eat a proper meal or sleep. If you manage diabetes or another condition affected by irregular eating: a day of smaller or delayed meals while caregiving can still affect you — keep your usual monitoring and treatment plan close at hand even when the day doesn''t go as planned. Feeding a sick child well and feeding yourself well are not competing tasks this week — they''re both part of getting the household through to the other side of this illness.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "A sick day rarely goes as planned. Meals get skipped, plans get dropped, and everyone in the house ends up running on whatever''s easiest to grab. This week is about keeping a little structure for your own eating even while your child''s routine is upside down.", "breakfast_a": "Vegetable dalia with roasted peanuts", "breakfast_b": "Egg-and-tomato omelette with toast", "lunch_a": "Rice with a moong dal and a carrot sabzi", "lunch_b": "Chicken curry with rice and a carrot sabzi", "nourishment_break_a": "Roasted peanuts with a mandarin (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Buttermilk with roasted cumin and a small bowl of roasted chana", "dinner_a": "Roti with a chana dal and a carrot sabzi", "dinner_b": "Paneer-peas curry with roti", "still_hungry": "A banana"}, {"day_number": 2, "title": "When your child won''t eat", "notes": "A reduced appetite during illness is common and usually resolves as your child recovers. Offering small amounts of familiar, easy foods — without pressure or bargaining — respects that appetite rather than fighting it. For your child: A reduced appetite is common during many short illnesses. Continue breastfeeding and usual milk feeds, and offer familiar age-appropriate food without pressure. Water may be offered as usual. If vomiting or diarrhoea is causing fluid loss, use a commercially prepared oral rehydration solution when advised or according to appropriate paediatric guidance; mix it exactly as directed. Do not replace ORS with sports drinks, soft drinks or homemade mixtures. Seek medical advice if your child is drinking markedly less, passing much less urine, repeatedly vomiting, unusually sleepy or irritable, difficult to wake, or otherwise becoming more unwell — even if poor appetite is the first thing you noticed. Large quantities of juice and other high-sugar drinks can worsen diarrhoea, while ORS is specifically formulated to replace fluid and electrolytes.", "breakfast_a": "Plain idli with sambar", "breakfast_b": "Egg-and-carrot bhurji with toast", "lunch_a": "Rice with a masoor dal and a cooked vegetable", "lunch_b": "Chicken curry with roti and a cooked vegetable", "nourishment_break_a": "A pear with roasted chana", "nourishment_break_b": "Curd with a spoon of soaked sabja seeds", "dinner_a": "Roti with a toor-moong dal and a cooked vegetable", "dinner_b": "Paneer-and-spinach curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "The old bland-diet advice, updated", "notes": "Bananas, rice, applesauce and toast can each be offered if a child enjoys and tolerates them, but together they do not form a complete recovery diet. There is no need to restrict a child to those four foods. For your child: Continue breastfeeding. During active vomiting, small frequent amounts of an appropriate fluid may be easier to tolerate than a full meal. As symptoms ease, offer familiar age-appropriate foods in whatever amount your child wants. During uncomplicated diarrhoea without repeated vomiting, children can generally continue their usual diet as tolerated; prolonged fasting or an unnecessarily restrictive diet is not recommended.", "breakfast_a": "Vegetable poha with a squeeze of lemon", "breakfast_b": "Egg-and-tomato bhurji with toast", "lunch_a": "Rice with a toor dal and a cooked vegetable", "lunch_b": "Fish-and-tomato curry with rice and a cooked vegetable", "nourishment_break_a": "A pear with plain curd", "nourishment_break_b": "A glass of milk with a banana", "dinner_a": "Roti with a rajma-lauki curry", "dinner_b": "Mutton-and-tomato curry with roti", "still_hungry": "A boiled egg"}, {"day_number": 4, "title": "If dehydration or serious illness raises a flag", "notes": "Most childhood illnesses pass with rest, fluids and time. A smaller number of signs mean it''s time to stop watching and start calling for medical advice. \"High fever\" alone is not the only — or always the most important — measure of how serious things are. For your child: Offer oral rehydration solution — not a sports or sweetened electrolyte drink — mixed exactly as directed on the packet, in small frequent sips if your child is vomiting. Continue breastfeeding alongside it. Get emergency help immediately if your child is struggling to breathe, has blue, grey or unusually pale lips or skin, has a first seizure, cannot be woken normally, or develops a rash that does not fade when pressed. Seek prompt medical advice for markedly reduced urine, a very dry mouth, sunken eyes, persistent vomiting that prevents fluids staying down, blood in the stool, a fever that is persistent or accompanied by worsening behaviour, or any child who appears to be getting more unwell. Fever thresholds depend on age; follow the advice applicable to your child. Seek help whenever you are seriously concerned, even if the exact symptom is not listed. This is not the day to try a new food, introduce a supplement, or start an unfamiliar remedy — keep things simple and familiar until they''re clearly on the mend. Wash hands with soap and water after nappies, toileting, vomit or stool cleanup and before preparing food. Clean frequently touched surfaces, and avoid sharing cups or utensils while someone is unwell. For you: ORS is not a substitute for your meals. Even if your child is managing only small sips, continue eating simple but complete food yourself.", "breakfast_a": "Vegetable upma with curd", "breakfast_b": "Fully cooked eggs with toast and a banana", "lunch_a": "Rice with moong dal and a soft cooked vegetable", "lunch_b": "Chicken-and-vegetable soup with rice", "nourishment_break_a": "A banana with plain curd", "nourishment_break_b": "Roasted chana with a glass of buttermilk", "dinner_a": "Soft vegetable khichdi with curd", "dinner_b": "Paneer bhurji with rice and a cooked vegetable", "still_hungry": "Warm milk or toast with curd"}, {"day_number": 5, "title": "Feeding yourself while you''re the one holding it", "notes": "Caring for a sick child is its own kind of full-time work — checking a temperature, offering sips, sitting through a nap that only happens on you. It''s easy for your own last proper meal to have been many hours ago without you quite noticing. Worth knowing: Keep a few foods on hand that need no real preparation — a piece of fruit, boiled eggs made in advance, curd, nuts, a flask of tea. Eating something simple now is more useful to you than waiting for a chance to cook the ideal meal.", "breakfast_a": "Moong dal cheela with tomato chutney", "breakfast_b": "Egg-and-capsicum bhurji with toast", "lunch_a": "Rice with a chana-methi curry", "lunch_b": "Paneer-and-methi curry with rice", "nourishment_break_a": "A mandarin with roasted chana for the adult; offer the child appropriately prepared soft fruit", "nourishment_break_b": "A glass of milk with smooth walnut paste spread thinly on soft toast, if walnut has already been safely introduced", "dinner_a": "Roti with a masoor dal and a cooked vegetable", "dinner_b": "Chicken-and-lauki curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "When the rest of the household needs to step up", "notes": "One person cannot be the only one tracking medicine doses, cooking, comforting a child and eating regular meals for days in a row. If there''s a partner, family member or friend who can take over even one meal or one stretch of childcare, this is a reasonable week to ask.", "breakfast_a": "Besan chilla with a grated carrot filling", "breakfast_b": "Boiled eggs with whole-grain toast and a pear", "lunch_a": "Rice with a masoor-matki dal and a cooked vegetable", "lunch_b": "Chicken-and-spinach curry with rice and a cooked vegetable", "nourishment_break_a": "An orange with roasted chana", "nourishment_break_b": "Curd with finely ground melon seeds for the adult; do not offer whole seeds to the young child", "dinner_a": "Roti with a lobia-tomato curry", "dinner_b": "Fish curry with roti and a cooked vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. During the last stretch of illness in your house, was there a moment when feeding yourself became especially difficult? What food, preparation or practical support might make that moment easier next time?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat your own meals as part of caring for a sick child, not something that waits until they''re better?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: caring for your child well includes caring for yourself while you do it.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 61: Eating well while you're grieving
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   61,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well while you''re grieving',
   '"Grief can take your appetite; it doesn''t have to take your care."',
   'Grief reorganizes a day the same way illness or upheaval does — plans lose their shape, ordinary tasks feel heavier, and eating is often one of the first things to become difficult, whether that means barely wanting food or reaching for it constantly. Grief, stress, disrupted sleep and changes in daily routine can all affect appetite. You may barely want food, eat more often, or turn toward familiar comfort foods — and none of these responses means you are grieving "wrong." If eating very little continues for more than a few days, or comes with noticeable weight loss, it''s worth mentioning to a doctor — not because grief itself is a medical problem, but because your body still needs fuel to get through it. This week doesn''t ask you to eat perfectly, or even normally. It offers small, low-effort ways to keep feeding yourself through a stretch of time when very little feels manageable.',
   'If you manage a condition such as diabetes, thyroid disease or high blood pressure: grief can disrupt appetite, sleep and routine in ways that affect these conditions. Keep your usual monitoring and medication schedule as steady as you can, and tell your care team if intake has changed substantially. If you''re pregnant or breastfeeding while grieving: your usual pregnancy or breastfeeding nutrition and hydration needs continue even on days when eating feels impossible — small, frequent bites and fluids matter more than a complete meal. You do not need to wait for a particular timeline before asking for support: if grief is making everyday life, sleep, eating or caring for yourself or your family increasingly difficult, speak with a doctor, therapist or grief counsellor. Persistent and disabling grief can sometimes need more structured support, but only a qualified professional can assess that. If you monitor blood glucose: choose unsweetened porridge or dalia, leave out jaggery, and pair fruit or toast with curd, milk, egg, paneer, nuts or another protein you tolerate. Continue following your individual glucose and medication plan even if your portions are smaller than usual. Please seek urgent help now if you are thinking about harming yourself, feel unable to keep yourself or your child safe, or cannot manage immediate basic care. Contact your local emergency service or urgent mental-health service, and tell someone you trust who can stay with you. You do not have to manage that moment alone. There is no timeline you''re supposed to be on, and no "right" way to eat through this. Small, imperfect steps are still steps.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Grief reorganizes a day fast, the same way illness or a crisis does. Ordinary routines — including meals — often become the first casualty. This week doesn''t ask you to eat perfectly; it offers small, manageable ways to keep feeding yourself.", "breakfast_a": "Moong dal cheela with coriander chutney", "breakfast_b": "Egg-and-onion toast", "lunch_a": "Rice with a toor dal and a lauki sabzi", "lunch_b": "Chicken curry with rice and a lauki sabzi", "nourishment_break_a": "Roasted almonds with a banana (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of warm milk with a pinch of nutmeg", "dinner_a": "Roti with a moong dal and a pumpkin sabzi", "dinner_b": "Paneer curry with roti and a pumpkin sabzi", "still_hungry": "A banana"}, {"day_number": 2, "title": "When food has no appeal at all", "notes": "A vanished appetite is one of the most common responses to grief. It isn''t a sign that something is wrong with you, and it isn''t something to push through with willpower alone. Worth knowing: Start smaller than feels necessary — a few bites, a smoothie, a slice of toast. Building up from small, frequent amounts is often easier than aiming for a full meal. Pre-made, frozen or ready-to-eat food removes a step you may not have the energy for right now, and that''s a reasonable choice, not a shortcut to feel guilty about. If eating very little continues for more than a few days, or comes with noticeable weight loss, mention it to a doctor.", "breakfast_a": "A smoothie with milk, banana and a spoon of peanut butter, if that''s easier than a plate", "breakfast_b": "Buttered toast with plain curd or a fully cooked egg — start with whichever part feels manageable", "lunch_a": "Khichdi with a spoon of ghee, in whatever amount feels manageable", "lunch_b": "Dal soup with soft rice and a spoon of curd", "nourishment_break_a": "A few spoons of curd with a banana", "nourishment_break_b": "A glass of warm milk", "dinner_a": "Soft rice with a thin dal", "dinner_b": "A boiled egg with toast, if you can manage it", "still_hungry": "Whatever small amount feels possible right now — it counts"}, {"day_number": 3, "title": "When food becomes the thing that holds you together", "notes": "For some people, grief pulls the other way — toward food as comfort, routine or distraction. That''s just as normal a response as losing your appetite, and this week isn''t about correcting it. Worth knowing: Eating for comfort during a genuinely hard stretch isn''t a failure of discipline. If you notice it becoming the only way you''re managing difficult feelings, that''s worth mentioning to a doctor or counselor — not as a verdict on you, but as one more form of support available.", "breakfast_a": "Wheat dalia with jaggery and milk", "breakfast_b": "Egg-and-potato bhurji with toast", "lunch_a": "Rice with a rajma curry and a cooked vegetable", "lunch_b": "Mutton curry with rice and a cooked vegetable", "nourishment_break_a": "A small bowl of rice kheer", "nourishment_break_b": "Curd with roasted chana for the adult; do not offer whole roasted chana to the young child", "dinner_a": "Roti with a chana-tomato curry", "dinner_b": "Chicken-and-potato curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "Letting people feed you", "notes": "If someone offers to cook, bring a meal, or take your child for an afternoon so you can rest, accepting that help is not a failure to cope — it''s one of the most practical things grief support looks like. A meal someone else made, reheated and eaten straight from the container, is still a real meal.", "breakfast_a": "Idli with tomato chutney", "breakfast_b": "Egg-and-spinach toast", "lunch_a": "Rice with a masoor dal and a beans sabzi", "lunch_b": "Fish curry with rice and a beans sabzi", "nourishment_break_a": "Roasted walnuts with a guava (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of buttermilk with roasted jeera", "dinner_a": "Roti with a moong dal and a cauliflower sabzi", "dinner_b": "Paneer curry with roti and a cauliflower sabzi", "still_hungry": "A banana"}, {"day_number": 5, "title": "If grief doesn''t loosen its grip", "notes": "Grief naturally eases in intensity over time for most people, even while it never fully disappears. For some, it stays acute and disabling for far longer, in ways that don''t resolve on their own. Worth knowing: You do not need to wait for a particular timeline before asking for support. If grief is making everyday life, sleep, eating or caring for yourself or your family increasingly difficult, speak with a doctor, therapist or grief counsellor. Persistent and disabling grief can sometimes need more structured support, but only a qualified professional can assess that.", "breakfast_a": "Oats porridge with milk and a banana", "breakfast_b": "Boiled eggs with toast and an orange", "lunch_a": "Rice with a moong-masoor dal and a cooked vegetable", "lunch_b": "Chicken-and-tomato curry with rice and a cooked vegetable", "nourishment_break_a": "An orange with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing with the child and peanut has already been introduced safely", "nourishment_break_b": "Curd with finely ground sunflower seeds", "dinner_a": "Roti with a masoor-moong dal and a cooked vegetable", "dinner_b": "Prawn curry with roti and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "Grieving while still caring for a young child", "notes": "Caring for a young child doesn''t pause for grief. You may be doing the quiet, exhausting work of holding both at once — your own loss and your child''s ordinary needs. That combination deserves real food and real support, not just for your child''s sake, but for your own.", "breakfast_a": "Besan chilla with a tomato-onion salad", "breakfast_b": "Egg-and-mushroom toast", "lunch_a": "Rice with a chana dal and a cooked vegetable", "lunch_b": "Chicken-and-spinach curry with roti and a cooked vegetable", "nourishment_break_a": "A guava with roasted almonds (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of milk with soft date paste for the adult; if sharing, use a very small amount mixed smoothly into porridge or curd rather than pieces of sticky dried date", "dinner_a": "Roti with a rajma dal and a cooked vegetable", "dinner_b": "Mutton-and-capsicum curry with rice", "still_hungry": "A glass of warm milk"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Is there one small, low-effort way of feeding yourself this week that felt more possible than the others? That''s worth keeping, for now.", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let feeding yourself through this be enough, without needing it to look like eating "well" in the usual sense?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: caring for yourself doesn''t pause for hard seasons; it just may need to look smaller and gentler than usual.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 62: Eating well as you start to feel like yourself again
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   62,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well as you start to feel like yourself again',
   '"Feeling like yourself again isn''t about going back — it''s about enjoying who you''re becoming now."',
   'Somewhere in the second year, many mothers notice something shifting — a bit more energy, a flicker of interest in things beyond the next feed or nap, food that tastes like more than fuel again. It''s a genuinely good sign, and it''s worth noticing without suspicion. The transition into motherhood is sometimes called matrescence. It can involve lasting changes in identity, relationships, priorities and the way you experience your own needs. There is no single timeline for that transition, and a medical recovery milestone does not mark the end of it. Food is one of the ordinary places this shows up: wanting to cook something for the pleasure of it again, missing a favourite dish, looking forward to a meal out. None of that needs to be earned or justified — enjoying food again is allowed to just be enjoyable. If it isn''t happening yet, that''s common too. This timeline varies enormously, and there''s no schedule you''re behind on.',
   'If persistent low mood, or loss of interest or pleasure in things you used to enjoy — including food — continues for weeks and doesn''t lift: this is worth raising with a doctor. Depression or anxiety can persist into — or arise during — the second year after birth. Whatever label a clinician uses, persistent low mood, anxiety or loss of interest deserves support. Please seek urgent help now if you are thinking about harming yourself, feel unable to keep yourself or your child safe, or cannot manage immediate basic care. Contact your local emergency service or urgent mental-health service, and tell someone you trust who can stay with you. If you''re pregnant again or breastfeeding while this shift is still underway: continue your usual nutrition needs for that — this identity shift and a physical recovery timeline don''t have to move at the same pace. If you manage a chronic condition such as diabetes, thyroid disease or high blood pressure: as energy and appetite shift, your usual monitoring and treatment plan still applies — mention any noticeable change in intake or activity to your care team. If you monitor blood glucose: choose unsweetened milk, curd, porridge and drinks; pair fruit or toast with protein; and replace sabudana khichdi with vegetable poha or besan chilla if that works better with your individual glucose plan. If you manage high blood pressure: choose unsalted nuts and seeds, and use roasted cumin, mint or lemon instead of chaat masala when you need to limit sodium. There''s no single moment when you''ll feel "back to normal," because normal isn''t where this is headed — it''s somewhere new, and you''re allowed to enjoy getting there.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Somewhere in this stretch, many mothers notice a bit more energy or curiosity returning — including around food. If that''s starting to happen for you, this week is about welcoming it, not questioning it.", "breakfast_a": "Vegetable paratha with curd", "breakfast_b": "Egg-and-capsicum toast", "lunch_a": "Rice with a moong dal and a beans sabzi", "lunch_b": "Chicken curry with rice and a beans sabzi", "nourishment_break_a": "Roasted peanuts with a guava (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of buttermilk with roasted cumin", "dinner_a": "Roti with a chana dal and a pumpkin sabzi", "dinner_b": "Paneer curry with roti and a spinach sabzi", "still_hungry": "A banana"}, {"day_number": 2, "title": "Rediscovering foods you used to love", "notes": "A craving for a specific dish, a memory of a favourite restaurant, a sudden urge to cook something just because you want to — these are ordinary signs of appetite for life returning, not indulgences to feel wary of.", "breakfast_a": "Besan chilla with mint chutney", "breakfast_b": "Egg-and-tomato toast", "lunch_a": "Rice with a toor dal and a capsicum sabzi", "lunch_b": "Chicken curry with rice and a capsicum sabzi", "nourishment_break_a": "A pear with roasted walnuts (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "Curd with finely ground flaxseed", "dinner_a": "Roti with a masoor dal and a lauki sabzi", "dinner_b": "Mutton curry with roti and a cauliflower sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 3, "title": "Cooking as something other than a chore", "notes": "If you have a bit more energy or time than you did earlier, cooking can become something other than one more task to get through — a new recipe, an ingredient you haven''t used in a while, something made purely because it sounded good. If cooking still feels like one more thing to manage right now, that''s fine too — this is an invitation, not a new obligation.", "breakfast_a": "Vegetable uttapam with tomato chutney", "breakfast_b": "Egg-and-onion bhurji with toast", "lunch_a": "Rice with a rajma dal and a carrot sabzi", "lunch_b": "Paneer curry with rice and a carrot sabzi", "nourishment_break_a": "A mandarin with roasted chana for the adult; do not offer whole roasted chana to the young child", "nourishment_break_b": "A glass of milk with a banana or a small piece of unsweetened paneer", "dinner_a": "Roti with a chana-spinach curry", "dinner_b": "Chicken-and-capsicum curry with roti", "still_hungry": "A boiled egg"}, {"day_number": 4, "title": "Eating out and feeling normal again", "notes": "Eating out with a young child can feel very different from the anxious, exhausting version of it in the earlier months. If it''s starting to feel more like an outing you enjoy than a logistics exercise to survive, that''s worth noticing. Worth knowing: Choose freshly cooked food served hot, ask for milder seasoning when sharing with your child, check fish carefully for bones, and avoid unfamiliar ice, raw chutneys or uncooked accompaniments where food or water safety is uncertain. One enjoyable restaurant meal does not need to be nutritionally perfect.", "breakfast_a": "Masala dosa with sambar", "breakfast_b": "Egg-and-cheese toast", "lunch_a": "Rice with a toor-masoor dal and a cauliflower sabzi", "lunch_b": "Fish curry with rice and a cauliflower sabzi", "nourishment_break_a": "Roasted chana for the adult with a mandarin; do not offer whole roasted chana to the young child", "nourishment_break_b": "A glass of buttermilk with a pinch of chaat masala", "dinner_a": "Roti with a moong-chana dal and a cooked vegetable", "dinner_b": "Chicken tikka with roti and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 5, "title": "When \"feeling like yourself\" still feels far off", "notes": "The transition into motherhood does not follow one standard timetable. If \"feeling like yourself\" still feels far off, that does not mean you are behind. Worth knowing: If low mood, or a loss of interest in things you''d normally enjoy, has continued for weeks and shows no sign of lifting, it''s worth speaking with a doctor. Depression or anxiety can persist into — or arise during — the second year after birth. Whatever label a clinician uses, persistent low mood, anxiety or loss of interest deserves support. Please seek urgent help now if you are thinking about harming yourself, feel unable to keep yourself or your child safe, or cannot manage immediate basic care. Contact your local emergency service or urgent mental-health service, and tell someone you trust who can stay with you.", "breakfast_a": "Oats idli with coconut chutney", "breakfast_b": "Egg-and-carrot toast", "lunch_a": "Rice with a masoor-toor dal and a cooked vegetable", "lunch_b": "Paneer-and-tomato curry with rice", "nourishment_break_a": "A guava with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "Curd with chia seeds soaked until fully softened", "dinner_a": "Roti with a rajma-tomato curry", "dinner_b": "Mutton-and-spinach curry with rice", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "Making space for you at the table", "notes": "Making space for yourself at a table — with a partner, a friend, or just alone with a meal you chose — is not a small or frivolous thing. It''s a real, ordinary way of reclaiming a bit of your own life.", "breakfast_a": "Sabudana khichdi with finely ground peanuts mixed through, if peanut has already been safely introduced", "breakfast_b": "Egg-and-spinach bhurji with toast", "lunch_a": "Rice with a chana-lauki curry", "lunch_b": "Chicken-and-methi curry with rice", "nourishment_break_a": "An orange with roasted almonds (whole nuts and similarly hard foods remain choking hazards for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of milk with a spoon of smooth cashew paste stirred in (whole or soaked cashews remain choking hazards for young children; keep them adult-only)", "dinner_a": "Roti with a lobia dal and a cooked vegetable", "dinner_b": "Fish curry with rice and a cooked vegetable", "still_hungry": "A glass of warm milk"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Is there one small food-related pleasure — a dish, a restaurant, a way of cooking — that used to be yours, and that you might make room for again this week?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let "feeling like yourself again" be about becoming, not returning — and to let food be part of that pleasure rather than a test of it?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: this stretch of motherhood keeps changing, and your relationship with food gets to change right along with it, toward more ease, not less.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
