  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 63: Eating well when you're expecting again
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   63,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when you''re expecting again',
   '"This pregnancy gets to be its own — even while you''re still caring for the one before it."',
   'Finding out you''re expecting again is a different moment from thinking about whether to — this week is for the mothers who now are, while still very much in the middle of caring for the child they already have. Some nutrient needs rise again with this new pregnancy: folate intake matters from very early on, and iron needs increase, particularly worth attention if your levels hadn''t fully recovered from your last pregnancy or birth. If you conceived on the shorter side of the interval your care team may have discussed with you, that''s simply worth mentioning at your next appointment — the research on how much a short gap between pregnancies affects nutrient stores is still evolving, not a settled verdict on what will happen to you. Your needs depend partly on how far along this pregnancy is. In a singleton pregnancy, people who began pregnancy at a healthy weight generally do not need routine extra calories in the first trimester; average needs rise by about 340 calories a day in the second trimester and about 450 in the third. These are general estimates, not a target every mother must hit. Your starting weight, activity, medical conditions, nausea and whether you are still breastfeeding can all change what is appropriate for you. If you are not already taking an appropriate prenatal supplement, contact your maternity clinician or pharmacist promptly. Standard guidance commonly includes a prenatal vitamin containing at least 400 micrograms of folic acid, particularly before conception and during the first 12 weeks. Some medical histories require a different prescribed dose. Do not take two prenatal or postnatal multivitamins together, because excess amounts of some nutrients can be harmful.',
   'Contact your maternity clinician promptly for vaginal bleeding or new abdominal or pelvic pain. Seek emergency care for sudden or severe abdominal or pelvic pain, shoulder pain, fainting, marked weakness or severe dizziness. If you''re still breastfeeding your older child: continuing through a healthy, uncomplicated pregnancy is generally reassuring, though the evidence is more limited for higher-risk pregnancies. Ask your maternity clinician for individual advice if you have bleeding, abdominal or uterine pain, contractions, a history or signs of preterm labour, recurrent pregnancy loss, a multiple pregnancy, poor weight gain or another pregnancy complication — these don''t automatically mean you must stop; your clinician can help you weigh your particular risks, your older child''s needs and your preference. If you conceived less than about 18 months after your last birth, or had a caesarean birth: mention the interval and your birth history at your next appointment — this is worth an individual conversation with your care team, not a fixed rule. If your iron levels hadn''t fully recovered from your last pregnancy or birth: ask about rechecking them now rather than assuming this pregnancy will be identical to your last — needs are rising again regardless of where you started. If you can''t keep liquids down for more than about eight hours, or food for 24 hours: contact your care team urgently — this may be more than ordinary pregnancy nausea and can need medical support beyond food changes. If you manage diabetes: pregnancy usually brings different glucose targets and medication needs. Pair rice, poha, toast or crackers with protein where tolerated, choose unsweetened drinks, and contact your diabetes or maternity team early rather than using your postpartum targets unchanged. If you take levothyroxine: tell your prescriber promptly that you are pregnant, because monitoring and dosage may need review. Ask your pharmacist how to separate it from prenatal vitamins, iron or calcium; these can reduce levothyroxine absorption when taken together. If you manage high blood pressure or another chronic condition: a new pregnancy generally means updated monitoring and targets — check in with your care team rather than continuing your postpartum plan unchanged. There''s no need to have this pregnancy figured out yet. Steady meals, your prenatal supplement, and a little patience with yourself can support you through this stage of pregnancy.',
   'Meat, fish and eggs remain valuable protein and iron sources through this pregnancy, cooked fully. Keep fish to two to three servings a week, choosing varied, lower-mercury types (such as salmon, sardines, cod, or shrimp) and avoiding higher-mercury species like king mackerel, shark, swordfish, or tilefish.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "However this pregnancy arrived — planned for a while, or a surprise — it''s allowed to bring a mix of feelings alongside it. Today isn''t about changing anything yet; it''s simply about noticing that you''re eating for this pregnancy now, on top of everything else you''re already managing.", "breakfast_a": "Vegetable poha with curd", "breakfast_b": "Egg-and-coriander toast", "lunch_a": "Rice with a moong dal and a bottle gourd sabzi", "lunch_b": "Chicken curry with rice and a bottle gourd sabzi", "nourishment_break_a": "A banana with roasted almonds (whole nuts remain a choking hazard for young children; keep the adult portion separate)", "nourishment_break_b": "A small bowl of roasted makhana (keep whole roasted makhana away from young children; offer it finely ground and mixed into a soft food if sharing)", "dinner_a": "Roti with a chana dal and a carrot sabzi", "dinner_b": "Fish curry with rice and a carrot sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "Restarting prenatal nutrition", "notes": "Folate and iron needs rise again with this pregnancy, much as they did with your last one. If you''re not already taking an appropriate prenatal supplement, contact your maternity clinician or pharmacist promptly. Standard guidance commonly includes a prenatal vitamin containing at least 400 micrograms of folic acid, especially before conception and through the first 12 weeks. If you are further along, continue your prenatal supplement as advised rather than assuming it is too late to benefit. Avoid taking a prenatal and a postnatal supplement together, since excess amounts of some nutrients can be harmful. For you: Iron-rich foods (dal, spinach, eggs, meat) alongside a source of vitamin C at the same meal help your body absorb iron better — worth doing whether or not your last iron levels had fully recovered.", "breakfast_a": "Moong dal chilla with mint chutney", "breakfast_b": "Egg bhurji with toast and orange segments", "lunch_a": "Rice with a rajma curry and a beetroot sabzi", "lunch_b": "Mutton curry with rice and a beetroot sabzi", "nourishment_break_a": "An orange with roasted peanuts for the adult; do not offer whole roasted peanuts to the young child", "nourishment_break_b": "Curd with a spoon of finely ground flaxseed", "dinner_a": "Roti with a palak-chana curry", "dinner_b": "Paneer-and-spinach curry with roti", "still_hungry": "A boiled egg"}, {"day_number": 3, "title": "Energy for two kinds of care", "notes": "If you are in the first trimester, you may not need a larger overall intake yet. If you are further along — or are also breastfeeding — your energy needs may be higher. Appetite and individual guidance matter more than forcing one standard portion. If your energy is low, letting a partner, family member, or friend take over a meal or a chunk of toddler-care for a stretch isn''t a failure to manage things yourself — it''s a reasonable way to get through a demanding few weeks.", "breakfast_a": "Vegetable dalia with curd", "breakfast_b": "Egg-and-methi toast", "lunch_a": "Rice with a masoor dal and a cauliflower sabzi", "lunch_b": "Chicken curry with rice and a cauliflower sabzi", "nourishment_break_a": "A pear with roasted walnuts (whole nuts remain a choking hazard for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of milk with a banana", "dinner_a": "Roti with a chana-methi curry", "dinner_b": "Egg curry with roti and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "If you''re still breastfeeding", "notes": "Available evidence is generally reassuring about continuing breastfeeding during a healthy, uncomplicated pregnancy, but the evidence is more limited for higher-risk pregnancies. Breastfeeding also adds to the nutritional and practical demands already placed on you. Worth knowing: Ask your maternity clinician for individual advice if you have vaginal bleeding, abdominal or uterine pain, contractions, a history or signs of preterm labour, recurrent pregnancy loss, a multiple pregnancy, poor weight gain or another pregnancy complication. These circumstances do not automatically mean you must stop; your clinician can help weigh your particular risks, your older child''s needs and your preference. For you: Meeting both this pregnancy''s needs and ongoing breastfeeding at the same time asks more of you nutritionally — steady meals, fluids, and rest matter more than any single food choice.", "breakfast_a": "Besan chilla with tomato chutney", "breakfast_b": "Egg-and-beetroot toast", "lunch_a": "Rice with a toor dal and a cabbage sabzi", "lunch_b": "Fish curry with rice and a cabbage sabzi", "nourishment_break_a": "A guava with roasted chana for the adult; do not offer whole roasted chana to the young child", "nourishment_break_b": "A glass of buttermilk with a pinch of roasted cumin", "dinner_a": "Roti with a rajma-carrot curry", "dinner_b": "Chicken-and-spinach curry with roti", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "When nausea makes eating hard", "notes": "Nausea, food aversions, and tiredness can return with this pregnancy much as they did before — and they''re not easier to manage the second time around simply because you already know them, especially with a toddler who still needs meals, patience, and attention. Small, frequent, plain meals are often easier than three big ones right now — there''s no need to \"eat properly\" if a cracker and a banana is what actually stays down. Worth knowing: Contact your care team urgently if you cannot keep liquids down for more than about eight hours, cannot eat for 24 hours, are passing very little or very dark urine, feel persistently dizzy or faint, are losing weight, vomit blood, or have fever or significant abdominal pain. Seek emergency care if you faint, become confused or feel severely unwell.", "breakfast_a": "Plain toast with banana and a few spoons of curd, if tolerated", "breakfast_b": "Curd rice with a few pomegranate seeds (mash or press the seeds if sharing with your child)", "lunch_a": "Khichdi with curd", "lunch_b": "Plain rice with a mild moong dal", "nourishment_break_a": "Plain crackers with curd or a small piece of paneer (offer only an age-appropriate cracker texture, with your child seated and supervised, if sharing)", "nourishment_break_b": "Lemon water without added sugar; add salt only if your clinician has advised it or you do not need to limit sodium", "dinner_a": "Roti with a mild potato-and-pea sabzi", "dinner_b": "Plain rice with a protein-forward mild dal as the anchor, and a steamed vegetable", "still_hungry": "Plain crackers with curd, milk or a small piece of paneer — whichever stays down"}, {"day_number": 6, "title": "Making room for you amid two sets of needs", "notes": "Between a toddler''s needs and a new pregnancy''s, it''s easy for your own meals to become an afterthought again. Making room for a proper plate for yourself — not just finishing what''s left on your child''s — is a genuinely worthwhile use of a few minutes today.", "breakfast_a": "Vegetable uttapam with coconut chutney", "breakfast_b": "Egg-and-tomato bhurji with toast", "lunch_a": "Rice with a chana-pumpkin curry", "lunch_b": "Mutton-and-methi curry with rice", "nourishment_break_a": "An apple with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A glass of milk with a spoon of smooth almond butter stirred in until fully dispersed (do not offer a spoonful or thick lump to your child; only if almond has already been safely introduced)", "dinner_a": "Roti with a moong-spinach dal", "dinner_b": "Paneer-and-tomato curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. What''s one thing — help from someone, a slower morning, a meal you don''t have to cook yourself — that would make this stretch a little easier to carry?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let this pregnancy be its own experience — not a repeat of your last one, and not something to manage perfectly alongside everything else you''re already carrying?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: your own nourishment keeps mattering, whatever else is unfolding around it.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 64: Eating well when you're parenting solo for a stretch
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   64,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when you''re parenting solo for a stretch',
   '"You don''t have to cook well this week — you just have to get through it, fed."',
   'A work trip, an unusually demanding stretch at the office, a visiting relative who needed more care than you did — whatever is keeping your usual support away right now, parenting solo for a while genuinely changes what''s realistic to cook, eat, and manage. This week isn''t about finding a clever system to keep everything running exactly as before. It''s about getting through a demanding stretch reasonably well-fed — you and your child both — using shortcuts that would ordinarily feel like cutting corners but are simply sensible right now. Batch-cooking one dish in a bigger quantity, leaning on convenience staples without guilt, and letting your child''s growing independence at the table do some of the work are all genuinely sound strategies here, not compromises to feel apologetic about. However long this stretch lasts, it''s temporary — and your usual way of cooking and eating can simply pick back up once it passes.',
   'If you manage a chronic condition such as thyroid disease: keep taking your medication and monitoring on schedule even on the most demanding days this week — a solo stretch is exactly when it''s easiest, and least advisable, to let this slip. If you''re still breastfeeding: your own fluids and meals matter more, not less, right now — regular meals and fluids can help support your energy and nutritional needs. If you notice yourself skipping meals most days, or living mainly on your child''s leftovers: that''s worth deliberately changing rather than accepting as how this stretch has to go — even a very simple meal eaten on a regular schedule is better than none. If you manage diabetes: avoid skipping meals and try to pair rice, roti, toast, or fruit with a protein or fibre-rich food. Continue following your prescribed monitoring and medication plan; do not rely on this general menu to replace it. If you manage high blood pressure: packaged foods, ready-made meals, pickles, papad, sauces, and takeaway dishes can be high in sodium. When practical, compare labels, choose lower-sodium options, request less salt, and balance convenience foods with fruit, curd, dal, or a simply cooked vegetable. If low mood, anxiety, or loss of interest persists, interferes with daily life, or feels difficult to manage: speak with a healthcare professional rather than waiting for this stretch to end. Seek urgent help for thoughts of harming yourself or your child, feeling detached from reality, severe confusion, or hearing or seeing things others do not. There''s no version of this week that has to look impressive. Fed, on schedule, and through it is entirely enough.',
   'Meat, fish and eggs remain quick, low-effort protein sources this week, cooked fully. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Whether it''s a work trip, a demanding stretch at the office, or something else keeping your usual support away for now, parenting solo for a while is genuinely harder — not something you''re managing badly if it feels that way. This week lowers the bar on purpose.", "breakfast_a": "Vegetable upma with curd", "breakfast_b": "Egg-and-potato toast", "lunch_a": "Rice with a moong dal and a lauki sabzi", "lunch_b": "Chicken curry with rice and a lauki sabzi", "nourishment_break_a": "A banana with roasted walnuts (whole nuts remain a choking hazard for young children; keep the adult portion separate)", "nourishment_break_b": "A glass of buttermilk with a pinch of black pepper", "dinner_a": "Roti with a chana dal and a beetroot sabzi", "dinner_b": "Egg curry with roti and a beetroot sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "One meal, made once, eaten twice", "notes": "Cooking one bigger batch of something you and your child both eat — and repeating it across a couple of meals — is not a lesser way to feed your family this week. It''s a genuinely sound way to get through it. A single one-pot dal, khichdi, or curry made in a larger quantity can cover today''s lunch and dinner with almost no extra effort the second time.", "breakfast_a": "Besan chilla with coriander chutney", "breakfast_b": "Egg bhurji with toast", "lunch_a": "Khichdi with curd — make enough for dinner too", "lunch_b": "Mutton curry with rice and a beans sabzi — make enough curry for dinner too", "nourishment_break_a": "An apple with roasted chana for the adult; do not offer whole roasted chana to the young child", "nourishment_break_b": "A glass of buttermilk with a pinch of ajwain", "dinner_a": "The extra khichdi from lunch, reheated until steaming hot, with curd", "dinner_b": "The extra mutton curry from lunch, reheated until steaming hot, with roti and any remaining beans sabzi", "still_hungry": "A boiled egg"}, {"day_number": 3, "title": "A real meal for you too, not just what''s left on your child''s plate", "notes": "It''s easy for your own lunch to become whatever your toddler didn''t finish. Today''s about a proper plate for you — served at the same time as your child''s, not assembled from its leftovers. For you: Keep a couple of ready-to-eat proteins on hand — boiled eggs, roasted chana, a block of paneer — so a real meal for you takes minutes, not another round of cooking.", "breakfast_a": "Vegetable dosa with tomato chutney", "breakfast_b": "Egg-and-spinach toast", "lunch_a": "Rice with a rajma curry and a beans sabzi", "lunch_b": "Fish curry with rice and a beans sabzi", "nourishment_break_a": "A pear with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "A bowl of curd with a banana", "dinner_a": "Roti with a masoor dal and a cooked vegetable", "dinner_b": "Chicken-and-methi curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "Making mealtimes easier without a second pair of hands", "notes": "At this age, your child may be beginning to use a spoon, drink from a cup, and manage a growing range of appropriately prepared finger foods — but these skills develop at different times. Leaning into whatever independence your child already has today makes mealtimes a little easier to run solo. For your child: Offer two or three simple finger foods prepared for your child''s developmental stage. Keep your child seated upright, stay close, and watch continuously while they eat. A calm, unhurried meal with minimal distraction can also reduce choking risk. Prepare every shared food for your child''s developmental stage: cook beans until very soft and mash or flatten them as needed, remove all bones from fish and meat, cut food into safe shapes and sizes, and avoid whole nuts, seeds, roasted chana, and spoonfuls or thick lumps of nut butter.", "breakfast_a": "Idli with coconut chutney", "breakfast_b": "Egg-and-mushroom toast", "lunch_a": "Rice with a toor dal and a beetroot sabzi", "lunch_b": "Mutton-and-capsicum curry with rice", "nourishment_break_a": "A pear with roasted almonds for the adult; do not offer whole roasted almonds to the young child", "nourishment_break_b": "An apple with roasted walnuts (whole nuts remain a choking hazard for young children; keep the adult portion separate)", "dinner_a": "Roti with a chana-beans curry", "dinner_b": "Paneer-and-capsicum curry with roti", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "When this week feels like genuinely too much", "notes": "Some days in a stretch like this will simply be harder than others, and that''s ordinary, not a sign you''re failing at it. A takeaway dinner, a frozen meal, or toast for the third time this week is a reasonable way through a genuinely demanding day. Worth knowing: Ordinary tiredness and overwhelm are expected here. If low mood, anxiety, or loss of interest persists, interferes with daily life, or feels difficult to manage, speak with a healthcare professional rather than waiting for this stretch to end. Seek urgent help for thoughts of harming yourself or your child, feeling detached from reality, severe confusion, or hearing or seeing things others do not.", "breakfast_a": "Plain toast with peanut butter", "breakfast_b": "Curd rice with a boiled egg", "lunch_a": "Frozen or pre-made dal with rice and a quick sautéed vegetable", "lunch_b": "Curd rice with roasted peanuts", "nourishment_break_a": "A mandarin with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A glass of buttermilk", "dinner_a": "Takeaway or delivered food, whatever is easiest tonight — a protein alongside something plant-based is a nice bonus when easily available, but eating what''s manageable tonight is still enough", "dinner_b": "Roti with a quick moong dal and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "Letting someone else feed you for a change", "notes": "Accepting a cooked dish from a friend, a grocery delivery, or a relative''s offer to help isn''t a failure to manage on your own — it''s a genuinely sensible way to get through a stretch like this one. If someone offers to help, a specific answer — \"a cooked dinner on Thursday would help enormously\" — is often easier for them to act on than a general \"I''m fine, thank you.\"", "breakfast_a": "Vegetable idli with sambar", "breakfast_b": "Egg-and-capsicum bhurji with toast", "lunch_a": "Rice with a chana-carrot curry", "lunch_b": "Chicken tikka with rice and a cooked vegetable", "nourishment_break_a": "An orange with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A glass of milk with a spoon of smooth cashew paste stirred in", "dinner_a": "Roti with a moong-methi dal", "dinner_b": "Fish curry with rice and a lauki sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. What''s one shortcut from this week — a batch-cooked dish, a convenience staple, a friend''s offer of help — that''s worth keeping even after this stretch ends?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to measure this week by "we got through it, fed" rather than by how closely it resembled a normal week?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: good-enough, sustainable meals matter more than perfect ones, whatever this season of motherhood brings.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 65: Eating well when you and your partner don't agree on how to feed your child
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   65,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when you and your partner don''t agree on how to feed your child',
   '"You don''t need to agree on everything at the table — you just need a shared approach that keeps food calm and safe."',
   'Disagreements about how to feed a toddler are common between co-parents — over how much pressure to put on finishing a plate, how strict to be about treats, or simply how worried to get when a meal goes untouched. This week isn''t about deciding who''s right. One widely used approach in pediatric nutrition and childcare divides the job cleanly: a parent decides what food is offered, and when and where — the child decides whether to eat it, and how much. When both parents work from that same division, many day-to-day disagreements have less to argue about, whatever their individual style otherwise looks like. Pressuring, bribing, or rewarding a child to eat a particular food tends to backfire — research fairly consistently finds it makes the pressured food less appealing and the reward food more desirable, regardless of which parent is doing the pressuring. You and your partner don''t need identical rules on everything. What matters more is not undermining each other in front of your child, and reserving a truly united, non-negotiable stance for anything involving safety rather than everyday preference.',
   'If your child has a diagnosed food allergy or medical feeding plan: both parents and every caregiver need to follow the same clinician-provided plan. Read labels each time, prevent cross-contact during preparation and serving, keep prescribed emergency medication accessible, and make sure both parents know the child''s emergency action plan. Feeding therapy or a medical feeding plan takes priority over the general strategies in this week. If you''re worried your child isn''t eating enough to grow well: a paediatrician can assess growth over time far more reliably than any single day''s plate — that reassurance is worth getting before assuming more pressure at mealtimes is the answer. If you manage diabetes: maintain your prescribed meal, monitoring and medication schedule, and pair rice, roti, toast or fruit with protein or fibre where practical. If you manage high blood pressure: keep added salt, pickles, papad, packaged sauces and salty restaurant foods within the limits advised for you. If you take thyroid medication: continue taking it exactly as prescribed and maintain any required separation from iron or calcium supplements. If you''re still breastfeeding: your own meals and fluids matter just as much this week as any conversation about your toddler''s plate. A calmer table doesn''t require two parents who agree on everything — just two parents committed to keeping everyday differences calm and safety rules consistent.',
   'Meat, fish and eggs can sit comfortably in a regular week''s meals here, rotated for variety, whichever household''s tradition you''re drawing from. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Disagreeing over dessert rules, portion pressure, or how strictly a plate needs to be finished doesn''t mean either of you is feeding your child badly. It usually just means you grew up around a different table.", "breakfast_a": "Vegetable paratha with curd", "breakfast_b": "Egg-and-tomato toast", "lunch_a": "Rice with a moong dal and a cabbage sabzi", "lunch_b": "Chicken curry with rice and a cabbage sabzi", "nourishment_break_a": "A banana with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "For the adult: cucumber and carrot sticks with hummus. If sharing with your child: cook the carrot until soft and prepare both vegetables in a size and texture appropriate for your child''s development; keep your child seated and supervise continuously.", "dinner_a": "Roti with a chana dal and a pumpkin sabzi", "dinner_b": "Fish curry with rice and a pumpkin sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "Who decides what, and who decides how much", "notes": "One widely used approach splits the job cleanly: a parent decides what food is offered, and when and where it''s served; the child decides whether to eat it, and how much. Once that division is clear, a lot of the daily tug-of-war has somewhere to go. For your child: Offering the same meal to your child that you''re eating — without a running commentary on how much they should take — hands the \"how much\" decision back to them, which is exactly where it''s meant to sit. Prepare shared foods for your child''s developmental stage: cook beans until very soft and mash or flatten them as needed, remove every bone from fish and meat, cut tougher foods into safe sizes and textures, and avoid whole nuts, seeds, roasted chana, and thick lumps or spoonfuls of nut butter. Keep your child seated upright and watch continuously while they eat.", "breakfast_a": "Oats chilla with mint chutney", "breakfast_b": "Egg-and-cheese bhurji with toast", "lunch_a": "Rice with a rajma curry and a lauki sabzi", "lunch_b": "Mutton curry with rice and a lauki sabzi", "nourishment_break_a": "An orange with roasted almonds for the adult; do not offer whole roasted almonds to the young child", "nourishment_break_b": "Curd with a spoon of finely ground sesame seeds", "dinner_a": "Roti with a masoor dal and a carrot sabzi", "dinner_b": "Paneer curry with roti and a carrot sabzi", "still_hungry": "A boiled egg"}, {"day_number": 3, "title": "Why pressure and bribery tend to backfire", "notes": "\"Finish your vegetables and you can have dessert\" is a familiar bargain — and research on this is fairly consistent: it tends to make the vegetable less appealing and the dessert more prized, the opposite of what either parent usually wants. For you: If you and your partner land on different sides of this, it''s worth raising it as a shared strategy question — not a referendum on whose parenting is stricter or more relaxed.", "breakfast_a": "Rava dosa with tomato chutney", "breakfast_b": "Egg-and-capsicum toast", "lunch_a": "Rice with a toor dal and a cauliflower sabzi", "lunch_b": "Chicken-and-methi curry with rice", "nourishment_break_a": "A guava with roasted walnuts (whole nuts remain a choking hazard for young children; keep the adult portion separate)", "nourishment_break_b": "A small bowl of curd with a few pomegranate seeds (mash or press the seeds if sharing with your child)", "dinner_a": "Roti with a chana-spinach curry", "dinner_b": "Egg curry with roti and a beans sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "Different traditions, same table", "notes": "The way you were fed as a child and the way your partner was fed as a child were probably not identical — and neither tradition has to be declared the correct one for your family''s table to work. Whichever household''s food habits feel more familiar to you, they got worked out over a long time for real reasons — that''s worth some respect, even from the parent who didn''t grow up with them.", "breakfast_a": "Idli with sambar", "breakfast_b": "Egg-and-onion bhurji with toast", "lunch_a": "Rice with a masoor-toor dal and a beans sabzi", "lunch_b": "Mutton-and-tomato curry with rice", "nourishment_break_a": "An orange with roasted chana for the adult; do not offer whole roasted chana to the young child", "nourishment_break_b": "A mandarin with roasted pistachios (whole nuts remain a choking hazard for young children; keep the adult portion separate)", "dinner_a": "Roti with a rajma-tomato curry", "dinner_b": "Paneer-and-cabbage curry with roti", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "On the same chapter, not necessarily the same page", "notes": "You don''t need identical rules to avoid confusing your child. What matters more is not contradicting or undermining each other in front of them — a disagreement about dessert can wait for a quiet moment between the two of you. Worth knowing: Save a genuinely united, non-negotiable stance for anything involving safety — a diagnosed allergy, a choking-risk food, a medical feeding plan. Everyday preferences, like how firmly a plate needs finishing, have far more room for each parent to differ.", "breakfast_a": "Vegetable uttapam with tomato chutney", "breakfast_b": "Egg-and-carrot toast", "lunch_a": "Rice with a chana-lauki curry", "lunch_b": "Chicken tikka with rice and a carrot sabzi", "nourishment_break_a": "A pear with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A glass of milk with a spoon of smooth peanut butter stirred in until fully dispersed (do not offer a spoonful or thick lump to your child; only if peanut has already been safely introduced)", "dinner_a": "Roti with a masoor-methi dal", "dinner_b": "Fish curry with rice and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "A variable appetite is not automatically a problem", "notes": "Many feeding disagreements begin when a toddler eats less than expected at one meal or barely touches dinner after a larger lunch. Appetite commonly varies from meal to meal and day to day. If your child is active, generally well, and growing as expected, an occasional small meal is not usually something that needs correcting with pressure. Persistent concerns about growth, swallowing, pain, energy, or a very restricted range of foods deserve professional assessment. For your child: A toddler-sized serving is genuinely small. As a general starting guide — not a target or requirement — this may be around one-quarter of an adult portion, with roughly one tablespoon of a cooked vegetable per year of age. Start small, allow more when requested, and let your child''s appetite guide how much is eaten.", "breakfast_a": "Moong dal chilla with tomato chutney", "breakfast_b": "Egg-and-cucumber toast", "lunch_a": "Rice with a masoor dal and a lauki sabzi", "lunch_b": "Mutton-and-spinach curry with rice", "nourishment_break_a": "A mandarin with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "A glass of buttermilk with a few crushed mint leaves", "dinner_a": "Roti with a chana-carrot curry", "dinner_b": "Paneer-and-carrot curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Is there one mealtime rule you and your partner disagree on that''s actually worth raising together, away from the table, rather than re-litigating in front of your child?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to treat a mealtime disagreement with your partner as two people trying to get the same thing right, rather than one of you being wrong?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: a calmer table matters more than a perfectly agreed-upon one.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 66: Eating well now that milk is starting to crowd out mealtimes
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   66,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well now that milk is starting to crowd out mealtimes',
   '"Milk is part of the meal now — not a replacement for it."',
   'Somewhere around this stage, milk can quietly turn from a helpful part of your child''s diet into the main thing they''re eating — offered every time they''re upset, thirsty, tired, or just not that interested in dinner. For many children aged 12–24 months, about 16 ounces — or two cups — of plain whole cow''s milk a day is a useful guide, unless their clinician recommends differently. Regularly exceeding 24 ounces can crowd out other foods and increase concern about iron deficiency. Yogurt, curd and cheese also contribute to your child''s overall dairy intake, so milk is not the only way to meet dairy needs. The reason it matters isn''t that milk is unhealthy — it''s that cow''s milk itself has very little iron, and a child filling up on it has less appetite left for the iron-rich foods, like dal, egg, meat or leafy greens, that milk can''t replace. None of this calls for cutting milk out or making it a fight. A planned total across the day, water as the default drink in between, and steady consistency without pressure is a realistic, gradual way through this.',
   'If your child seems unusually pale, tired, or has a noticeably reduced appetite for food alongside heavy milk intake: mention this to your paediatrician — iron-deficiency anaemia related to excess milk intake is common enough to be worth ruling out rather than assuming it will resolve on its own. Do not start an iron supplement solely because milk intake seems high: iron deficiency should be assessed and supplements dosed by a healthcare professional, because excessive iron can also be harmful. If your child has a diagnosed milk allergy, lactose intolerance, or a medical feeding plan: follow that plan specifically — the general milk-quantity guidance in this week assumes a child without a diagnosed milk-related condition. Do not replace cow''s milk automatically with an unfortified plant drink; use the unsweetened, nutritionally appropriate alternative recommended for your child, and check that it supplies the calcium, vitamin D, protein and energy their diet requires. Not every plant-based drink is nutritionally equivalent to milk. If your child still uses a bottle at nap or bedtime: avoid leaving a bottle in bed or letting your child carry one throughout the day — if a bottle is temporarily still used during the transition, put only plain water in it while you continue moving toward an open or free-flow cup. If you manage diabetes: maintain your prescribed meal, monitoring and medication schedule, and pair rice, roti, fruit or toast with protein or fibre where practical. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you. If you take thyroid medication: continue it exactly as prescribed and maintain any required separation from iron or calcium supplements. Milk still has a place at this table — just not the whole table to itself.',
   'Meat, fish and eggs are valuable iron sources this week in particular, cooked fully. Keep fish to two to three servings a week, choosing varied, lower-mercury types and cooking it fully.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "If your child asks for milk before, during, and between every meal, and mealtimes have started feeling like a battle over food they barely touch, milk may have quietly become the main event instead of a part of it. This week is about gently shifting that balance back.", "breakfast_a": "Vegetable poha with curd", "breakfast_b": "Egg-and-beetroot toast", "lunch_a": "Rice with a moong dal and a beetroot sabzi", "lunch_b": "Chicken curry with rice and a beetroot sabzi", "nourishment_break_a": "A banana with roasted almonds for the adult; do not offer whole roasted almonds to the young child", "nourishment_break_b": "A glass of buttermilk with a pinch of roasted cumin", "dinner_a": "Roti with a chana dal and a carrot sabzi", "dinner_b": "Fish curry with rice and a carrot sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "How much milk is actually enough", "notes": "For a child over a year old, about 16 ounces (two cups) of milk a day is the commonly used benchmark. It''s easy to drift well past that without noticing, especially if milk is offered any time your child seems unsettled. For your child: If your child regularly drinks more than about 24 ounces — or three cups — of cow''s milk a day, discuss the pattern with their paediatrician and gradually work toward the amount recommended for them. Around 16 ounces may suit many children this age, but individual needs and the rest of the child''s diet matter. Prepare shared foods for your child''s developmental stage: cook beans until very soft and mash or flatten them as needed, remove all bones from meat and fish, avoid whole nuts, seeds, roasted chana and whole makhana, and keep nut butter thinly spread or fully mixed into soft food. Keep your child seated upright and supervise continuously while eating.", "breakfast_a": "Besan chilla with mint chutney", "breakfast_b": "Egg-and-tomato bhurji with toast", "lunch_a": "Rice with a rajma curry and a cauliflower sabzi", "lunch_b": "Mutton curry with rice and a cauliflower sabzi", "nourishment_break_a": "An orange with roasted walnuts for the adult; do not offer whole roasted walnuts to the young child", "nourishment_break_b": "Curd with a spoon of finely ground flaxseed", "dinner_a": "Roti with a masoor dal and a beetroot sabzi", "dinner_b": "Paneer curry with roti and a beetroot sabzi", "still_hungry": "A boiled egg"}, {"day_number": 3, "title": "Why too much milk can quietly cause iron trouble", "notes": "Cow''s milk itself has very little iron in it — so when it''s filling a child up ahead of iron-rich foods like dal, egg, meat, or leafy greens, both problems compound at once: less iron coming in, and less appetite left for the foods that would supply it. For your child: Serve a planned portion of milk as part of the meal, without requiring your child to eat a certain amount first and without automatically refilling the cup. Keep water as the usual drink between meals. This leaves more room for iron-rich foods without turning food and milk into another negotiation.", "breakfast_a": "Moong dal dosa with tomato chutney", "breakfast_b": "Egg-and-methi toast", "lunch_a": "Rice with a toor dal and a capsicum sabzi", "lunch_b": "Fish curry with rice and a capsicum sabzi", "nourishment_break_a": "A guava with roasted almonds for the adult; do not offer whole roasted almonds to the young child", "nourishment_break_b": "A small bowl of curd with a sliced banana", "dinner_a": "Roti with a chana-cauliflower curry", "dinner_b": "Egg curry with roti and a cooked vegetable", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "If the bottle is still part of the picture", "notes": "If your child still drinks from a bottle, this is a reasonable stage to be moving fully to a cup — bottles left in past 12 to 18 months are linked to both higher milk intake and more time teeth spend coated in milk. Worth knowing: A bottle carried around throughout the day, or used to settle your child at nap or bedtime, is one of the easiest ways milk volume creeps up unnoticed. Avoid leaving a bottle in bed or allowing your child to carry one throughout the day. If a bottle is temporarily still used during the transition, put only plain water in it and continue moving toward an open or free-flow cup.", "breakfast_a": "Rava idli with tomato chutney", "breakfast_b": "Egg-and-mushroom bhurji with toast", "lunch_a": "Rice with a masoor-toor dal and a cooked vegetable", "lunch_b": "Mutton-and-methi curry with rice", "nourishment_break_a": "A pear with roasted chana for the adult; do not offer whole roasted chana to the young child", "nourishment_break_b": "A small bowl of roasted makhana (keep whole roasted makhana away from young children; offer it finely ground and mixed into a soft food if sharing)", "dinner_a": "Roti with a rajma-carrot curry", "dinner_b": "Paneer-and-tomato curry with roti", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "Making the shift without a fight over it", "notes": "This isn''t a change to force through in a day. Choose two predictable milk servings — or divide your child''s recommended daily amount into smaller servings across meals — and make water the usual drink between meals. The aim is a planned total, not necessarily milk at every meal. Some resistance is understandable, and the adjustment may happen gradually. Consistency without pressure matters more than completing the change within a particular number of days.", "breakfast_a": "Vegetable uttapam with coconut chutney", "breakfast_b": "Egg-and-onion toast", "lunch_a": "Rice with a chana-pumpkin curry", "lunch_b": "Chicken tikka with rice and a beans sabzi", "nourishment_break_a": "An apple with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A glass of water with a banana and a small besan chilla", "dinner_a": "Roti with a moong-spinach dal", "dinner_b": "Fish curry with rice and a cauliflower sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 6, "title": "If you''re still breastfeeding", "notes": "Breastfeeding beyond a year remains nutritionally valuable and is supported for as long as it suits you and your child. Breast milk may still provide a meaningful share of energy and nutrients during the second year, while varied complementary foods provide the remainder. There is no need to impose a cow''s-milk limit on breastfeeding, but if frequent nursing consistently replaces meals or your child''s growth, iron intake or food variety concerns you, discuss the overall feeding pattern with their paediatrician. For your child: Once teeth have erupted, brush them twice daily with a smear of age-appropriate fluoride toothpaste, including after the final feed before sleep whenever practical. Avoid putting your child to bed with a bottle of milk. If frequent overnight nursing continues, keep daytime and bedtime brushing consistent and ask your child''s dentist for guidance suited to your feeding routine.", "breakfast_a": "Moong dal chilla with coriander chutney", "breakfast_b": "Egg-and-cheese toast", "lunch_a": "Rice with a masoor dal and a pumpkin sabzi", "lunch_b": "Mutton-and-carrot curry with rice", "nourishment_break_a": "An orange with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "A glass of coconut water", "dinner_a": "Roti with a moong-carrot dal", "dinner_b": "Paneer-and-methi curry with roti", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. Roughly how many cups of milk did your child actually have yesterday — and does that number surprise you?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let milk sit alongside your child''s meals as a steady, ordinary part of the table — rather than the thing that makes everything else optional?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: small, steady adjustments serve your child''s nourishment better than any single rule enforced all at once.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 67: Eating well as you wean your child off breastfeeding
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   67,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well as you wean your child off breastfeeding',
   '"Weaning gets to be gradual — for both of you."',
   'Weaning is often talked about as something that just needs to happen — dropped feeds, a bit of fussing, and then it''s done. In practice it''s a nutritional transition for your child and a physical and emotional one for you, and both go more smoothly slowly. This week is for mothers who have chosen — or need — to reduce or end breastfeeding. Continuing to breastfeed is equally valid. WHO supports breastfeeding alongside complementary foods for two years or beyond, for as long as it suits mother and child. At this stage, a dropped breastfeed does not automatically require a replacement drink if your child is eating a varied diet and growing well. Regular meals and nutritious snacks gradually take on more of the work. Plain whole cow''s milk — or an appropriate fortified alternative when advised — may form part of the diet, but it should not replace food or exceed the amount recommended for your child. For you, milk production usually decreases as nursing or expressing becomes less frequent. Reducing feeds abruptly can increase the likelihood of uncomfortable fullness, engorgement and breast inflammation, while a gradual reduction often gives your body more time to adjust. Weaning can also carry mixed emotions, but significant mood symptoms should not automatically be attributed to hormones or to the speed of weaning. When circumstances allow, reduce one feed at a time and pause long enough for your breasts, your child and your routine to adjust comfortably before reducing another. Some people need only several days between changes; others need longer. Pain, marked fullness or distress is a reason to slow down and seek support — not a reason to force the schedule. Gradual reduction is supported, but there is no single mandatory timetable.',
   'If your child seems unusually pale, tired, or has a reduced appetite as feeds drop: mention this to your paediatrician — it''s worth checking iron levels rather than assuming it will resolve on its own. If you notice fever, spreading redness, worsening breast pain, or feel acutely unwell as your supply eases: seek medical advice promptly rather than waiting to see if it settles — a qualified lactation professional can also help with feeding and milk-reduction technique. If weaning needs to happen quickly for a medical reason: such as a treatment or medication that isn''t compatible with breastfeeding, talk to your doctor or a lactation consultant about doing it safely — don''t delay care you need in order to keep breastfeeding. If your child has a diagnosed milk allergy or a medical feeding plan: follow that plan specifically when choosing what replaces dropped feeds — this week''s general guidance assumes a child without a diagnosed milk-related condition. For a child over one, do not assume every plant drink is nutritionally equivalent to cow''s milk. Use an unsweetened, appropriately fortified alternative recommended for your child and check its protein, energy, calcium and vitamin D content. If you manage diabetes: maintain your prescribed meal, monitoring and medication schedule through this transition, and pair rice, roti, fruit or toast with protein or fibre where practical. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you. If you take thyroid medication: continue it exactly as prescribed and maintain any required separation from iron or calcium supplements. There''s no single right pace for weaning — only the one that keeps you both comfortable and well.',
   'Meat, fish and eggs can contribute protein and micronutrients this week. Meat and eggs can provide iron, while varied lower-mercury fish can provide omega-3 fats. Cook each fully and keep fish within the locally recommended weekly amount.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Weaning — whether it unfolds over months or needs to happen quickly — changes two things at once: what your child''s plate needs to cover, and what your own body and routine are adjusting to. This week holds space for both.", "breakfast_a": "Semolina upma with mixed vegetables", "breakfast_b": "Egg-and-spinach toast", "lunch_a": "Rice with a moong dal and a bhindi sabzi", "lunch_b": "Chicken curry with rice and a bhindi sabzi", "nourishment_break_a": "A papaya with roasted cashews for the adult; do not offer whole roasted cashews to the young child", "nourishment_break_b": "A glass of buttermilk with a pinch of roasted jeera", "dinner_a": "Roti with a chana dal and a tinda sabzi", "dinner_b": "Fish curry with rice and a tinda sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "Going slowly, on purpose", "notes": "Gradual reduction is often more comfortable than stopping abruptly, but there is no universal number of days that must pass between feeds. Reduce one feed at a time when circumstances allow, then pause until your breasts, your child and your routine feel reasonably settled before changing another. Some transitions unfold over weeks; others take months. For your child: There''s no fixed timeline that''s right for every family — some manage the full transition in a few weeks, others take several months. Both are normal; your child''s cues and your own circumstances can set the pace. Some families use a child-led approach — avoiding actively offering a feed while still responding flexibly when the child asks. Others prefer a planned reduction. Either approach can be adapted; the important points are avoiding unnecessary pressure, watching your own comfort and making sure your child''s meals, snacks and fluids remain adequate.", "breakfast_a": "Ragi dosa with tomato chutney", "breakfast_b": "Egg-and-cabbage bhurji with toast", "lunch_a": "Rice with a rajma curry and a capsicum sabzi", "lunch_b": "Mutton curry with rice and a capsicum sabzi", "nourishment_break_a": "A kiwi with roasted pistachios for the adult; do not offer whole roasted pistachios to the young child", "nourishment_break_b": "Curd with a spoon of roasted chia seeds", "dinner_a": "Roti with a masoor dal and a beans sabzi", "dinner_b": "Paneer curry with roti and a beans sabzi", "still_hungry": "A boiled egg"}, {"day_number": 3, "title": "What steps in for your child", "notes": "Once a feed is dropped, meals and snacks take on more of the job breastfeeding was doing — not a single replacement drink, but the overall pattern of what your child eats across the day. For your child: Keep regular meals and nutritious snacks centred on dietary variety. Include iron-rich foods such as well-cooked dal and beans, egg or meat, pairing plant sources with vitamin-C-rich fruit or vegetables where practical. Children aged 12–24 months need vitamin D from appropriate foods and, in some settings, a supplement; ask your child''s clinician what applies locally. Lower-mercury fish can provide omega-3 fats, but a special \"DHA replacement\" is not automatically required when breastfeeding decreases. Prepare shared foods for your child''s developmental stage: cook beans until very soft and mash or flatten them as needed, remove bones from meat and fish, finely shred fibrous drumstick flesh and discard the pod fibres, and avoid whole nuts, seeds and roasted chana. Serve chia soaked or finely ground rather than dry and whole. Keep your child seated upright and supervise continuously while eating.", "breakfast_a": "Oats idli with sambar", "breakfast_b": "Egg bhurji with toast", "lunch_a": "Rice with a toor dal and a mushroom sabzi", "lunch_b": "Chicken-and-mushroom curry with rice", "nourishment_break_a": "A chikoo with roasted almonds for the adult; do not offer whole roasted almonds to the young child", "nourishment_break_b": "A glass of milk with a pinch of turmeric", "dinner_a": "Roti with a chana-methi dal and a lauki sabzi", "dinner_b": "Egg curry with roti and a lauki sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "Caring for your body as milk supply eases", "notes": "Your body needs time to adjust too. Reducing feeds gradually rather than stopping abruptly can lower the likelihood of painful fullness and breast inflammation, but it cannot guarantee that symptoms will not occur. Your comfort and any developing warning signs should guide the pace. If you become uncomfortably full, hand-express or pump only enough for comfort rather than trying to empty the breast completely. Use a cold compress for swelling and avoid forceful or deep breast massage. Worth knowing: Seek medical advice promptly for fever, spreading redness, worsening breast pain, feeling acutely unwell, or symptoms that are not improving. A qualified lactation professional can also help with feeding and milk-reduction technique. Cold cabbage leaves can remain an optional comfort measure, but they haven''t been shown to work better than an ordinary cold compress.", "breakfast_a": "Moong dal cheela with mint chutney", "breakfast_b": "Egg-and-peas toast", "lunch_a": "Rice with a masoor dal and a peas sabzi", "lunch_b": "Fish curry with rice and a peas sabzi", "nourishment_break_a": "A mango with roasted walnuts for the adult; do not offer whole roasted walnuts to the young child", "nourishment_break_b": "A small bowl of curd with a grated apple", "dinner_a": "Roti with a rajma-pumpkin curry", "dinner_b": "Paneer-and-pumpkin curry with roti", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "If the timeline wasn''t yours to choose", "notes": "Not every weaning timeline is chosen freely — a medical treatment, an illness, or a return to work can all mean moving faster than you''d planned. If weaning needs to happen quickly for medical reasons, talk to your doctor or a lactation consultant about doing it safely; don''t delay treatment you need out of reluctance to stop breastfeeding. Weaning can bring mixed emotions, and some mothers notice changes in mood during the transition. The cause and intensity differ, so do not assume significant symptoms are simply hormonal or something you must wait out. For you: Speak with a healthcare professional if low mood, anxiety or loss of interest persists, interferes with daily life, or feels difficult to manage. Seek urgent help for thoughts of harming yourself or your child, severe confusion, feeling detached from reality, or hearing or seeing things others do not.", "breakfast_a": "Vegetable poha with peanuts", "breakfast_b": "Egg-and-bhindi toast", "lunch_a": "Rice with a chana dal and a turai sabzi", "lunch_b": "Chicken curry with rice and a turai sabzi", "nourishment_break_a": "A bowl of watermelon cubes with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A small bowl of moong-sprout chaat made with sprouts cooked thoroughly until steaming hot, cooled safely before serving, with a squeeze of lemon", "dinner_a": "Roti with a moong-tomato dal", "dinner_b": "Mutton curry with rice and a tomato sabzi", "still_hungry": "A boiled egg"}, {"day_number": 6, "title": "What tells you your child needs more, not less", "notes": "As feeds drop and food and other drinks take over, it''s worth knowing what tells you the transition is moving faster than your child''s intake can keep up with — especially for a younger toddler. For your child: Watch for clearly fewer wet diapers than usual, a dry mouth, few or no tears, unusual tiredness, reduced activity, or difficulty drinking. Contact your child''s healthcare professional the same day for suspected dehydration. Seek urgent care if your child is difficult to wake, unable to keep fluids down, breathing unusually, or becoming rapidly less responsive. Checking in with your child''s paediatrician before or during weaning is worth doing generally, especially if there are any existing feeding, growth, or health concerns.", "breakfast_a": "Besan chilla with coriander chutney", "breakfast_b": "Egg-and-paneer bhurji with toast", "lunch_a": "Rice with a masoor-toor dal and a beetroot sabzi", "lunch_b": "Mutton-and-beetroot curry with rice", "nourishment_break_a": "A bowl of muskmelon with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "A glass of buttermilk with a few crushed curry leaves", "dinner_a": "Roti with a chana dal and a drumstick sabzi", "dinner_b": "Fish curry with rice and a drumstick sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. If you''re partway through weaning, how has the pace felt so far — steady, rushed, or somewhere in between?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let this transition take as long as it actually needs — for your child''s plate, and for your own body — rather than the length of time you think it "should" take?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: small, steady adjustments serve your child''s nourishment better than any single rule enforced all at once.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 68: Eating well when your toddler is stuck on the same few foods
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   68,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when your toddler is stuck on the same few foods',
   '"This is a phase to move through together — not a habit to break."',
   'A food jag — when a child repeatedly asks for or accepts the same small group of foods — is common during toddlerhood. It may last days or weeks and can recur as preferences, appetite and development change. If your child remains active, generally well and growing as expected, a short repetitive phase is usually more useful to observe calmly than to confront. Wariness of unfamiliar foods is developmentally common. Taste, smell, texture, appearance and the desire for predictability can all make familiar foods feel safer, especially when a toddler is tired, teething, unwell or seeking more control — reasons that have little to do with your cooking or your child''s overall appetite. What tends to help: keep serving the jag food without letting it become the only thing offered, keep quietly offering new foods alongside it without pressure, and judge how things are going across a week or two rather than any single meal. Most jags resolve on their own without any dramatic intervention. This week also covers the smaller set of signs that are worth a conversation with your paediatrician, so you know the difference between an ordinary phase and something worth a closer look.',
   'If your child seems unusually pale, tired, or has a noticeably reduced appetite: mention this to your paediatrician — it''s worth checking iron levels rather than assuming it will resolve on its own. If the accepted range remains extremely narrow or keeps shrinking over time: mention the pattern to your paediatrician — especially if entire food groups or age-appropriate textures are absent, meals regularly cause distress, eating takes unusually long, chewing or swallowing appears difficult, or growth, energy or nutrition is affected. The number of accepted foods can provide useful context, but no single number diagnoses a feeding disorder. If your child shows real distress — crying, gagging, or vomiting — at the sight of a new food: rather than simple reluctance, this is different from ordinary wariness and is worth discussing with your paediatrician. If the jag food carries a choking risk: prepare it in a developmentally safe form when that is possible — or do not serve it yet when it cannot be made safe. Quarter grapes lengthwise, avoid popcorn and whole nuts, cook hard fruit and vegetables until soft, and spread nut or seed butter thinly rather than offering a spoonful or thick lump. If you manage diabetes: maintain your prescribed meal, monitoring and medication schedule, and pair rice, roti, fruit or toast with protein or fibre where practical. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you. If you take thyroid medication: continue it exactly as prescribed and maintain any required separation from iron or calcium supplements. A narrow week of eating is common enough to expect — it''s the trend over months, not the odd repetitive week, that''s worth watching.',
   'Meat, fish and eggs can contribute protein and micronutrients this week. Meat and eggs can provide iron, while varied lower-mercury fish can provide omega-3 fats. Cook each fully and keep fish within the locally recommended weekly amount.',
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "If mealtimes lately have meant the same two or three foods, on repeat, for what feels like the tenth day running — you''re not doing anything wrong, and neither is your child. This week is about riding out a food jag without it becoming a bigger fight than it needs to be. The choices below are for the family meal. For your child, include at least one currently accepted food alongside a very small portion of the family food when practical. Success this week means calm exposure and adequate nourishment — not eating every item listed.", "breakfast_a": "Vegetable dhokla with green chutney", "breakfast_b": "Egg-and-carrot bhurji with toast", "lunch_a": "Rice with a moong dal and a carrot sabzi", "lunch_b": "Chicken curry with rice and a carrot sabzi", "nourishment_break_a": "A bowl of pineapple chunks with roasted almonds for the adult; do not offer whole roasted almonds to the young child", "nourishment_break_b": "A glass of buttermilk with a pinch of ajwain", "dinner_a": "Roti with a chana dal and a beetroot sabzi", "dinner_b": "Fish curry with rice and a beetroot sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 2, "title": "Why this happens", "notes": "Food jags are a well-recognised, normal part of toddler development — not a sign you''ve done something wrong. Wariness of unfamiliar foods is developmentally common, and mealtime autonomy is one of the few things your child can fully control, which can make plain, predictable foods feel safer. For your child: This phase can recur as preferences, appetite and development change. Pulling the favourite food away entirely often backfires — the aim is to keep offering it without letting it crowd out everything else. Prepare all shared foods for your child''s developmental stage: cook beans until very soft and mash or flatten them as needed, remove bones from meat and fish, cut slippery or fibrous fruit into safe shapes and textures, and avoid whole nuts, seeds and roasted chana. Keep nut and seed butter thinly spread or fully mixed into soft food. Keep your child seated upright and supervise continuously while eating.", "breakfast_a": "Sooji cheela with tomato chutney", "breakfast_b": "Egg-and-methi bhurji with toast", "lunch_a": "Rice with a rajma curry and a beans sabzi", "lunch_b": "Mutton curry with rice and a beans sabzi", "nourishment_break_a": "A mosambi with roasted walnuts for the adult; do not offer whole roasted walnuts to the young child", "nourishment_break_b": "Curd with finely ground pumpkin seeds mixed through it; keep whole roasted pumpkin seeds for the adult portion only", "dinner_a": "Roti with a masoor dal and a capsicum sabzi", "dinner_b": "Egg curry with roti and a capsicum sabzi", "still_hungry": "A boiled egg"}, {"day_number": 3, "title": "Keep offering, without pressure", "notes": "A new food may need to appear many times — sometimes ten or more — before a toddler tastes or accepts it. Seeing, touching, smelling or tolerating it nearby can all be steps in learning. The number is not a target or deadline, and an untouched food can be offered again another day without comment. You decide what''s offered, when, and where; your child decides whether to eat it and how much — that division holds just as well during a jag as any other week. For you: Pressuring, bargaining, or using the jag food as a reward for trying something new tends to backfire — it can make the new food feel like a chore and the familiar one feel even more like the prize.", "breakfast_a": "Moong dal dosa with coconut chutney", "breakfast_b": "Egg-and-capsicum bhurji with toast", "lunch_a": "Rice with a toor dal and a brinjal sabzi", "lunch_b": "Fish curry with rice and a brinjal sabzi", "nourishment_break_a": "An orange with roasted cashews for the adult; do not offer whole roasted cashews to the young child", "nourishment_break_b": "A glass of milk with a pinch of cardamom", "dinner_a": "Roti with a chana-methi dal and a bhindi sabzi", "dinner_b": "Paneer curry with roti and a bhindi sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 4, "title": "Widening the circle without a fight", "notes": "Offer a very small amount of a similar food beside the familiar one — a similar shape, colour, or texture to the jag food. If having it on the same plate causes distress, use a separate side plate or simply let your child see it on the table. Exposure does not require touching, tasting or eating. A new food sitting untouched next to a familiar one still counts as exposure. Repetition, not persuasion, is usually what shifts things.", "breakfast_a": "Vegetable idli with sambar", "breakfast_b": "Egg-and-cucumber bhurji with toast", "lunch_a": "Rice with a masoor dal and a capsicum sabzi", "lunch_b": "Chicken-and-capsicum curry with rice", "nourishment_break_a": "A plum with roasted peanuts for the adult; use smooth peanut butter spread thinly if sharing", "nourishment_break_b": "A small bowl of curd with a grated pear", "dinner_a": "Roti with a rajma-tomato curry", "dinner_b": "Mutton-and-tomato curry with rice", "still_hungry": "A glass of warm milk"}, {"day_number": 5, "title": "Checking nutrition over the week, not the meal", "notes": "A single day of jag eating rarely matters nutritionally. What''s worth a glance is the pattern across a week or two — rough variety, energy levels, and how your child is growing over time, rather than any one meal. For your child: The nutrients most affected depend on which foods your child currently accepts. A pattern dominated by refined starches may provide limited fibre, iron and micronutrient variety, while avoidance of whole food groups can create different gaps. Look at the overall pattern with your paediatrician or a registered dietitian rather than trying to diagnose a deficiency from the jag food alone. If your child already accepts a food with ground seeds, nut butter or puréed vegetables mixed into it, that can add nourishment. Be matter-of-fact about what the food contains rather than disguising it, and avoid repeatedly changing a trusted food without warning. Continue offering foods visibly and without pressure so familiarity can grow over time.", "breakfast_a": "Rava dosa with mint chutney", "breakfast_b": "Egg-and-mushroom toast", "lunch_a": "Rice with a chana dal and a tinda sabzi", "lunch_b": "Mutton-and-tinda curry with rice", "nourishment_break_a": "A bowl of dragon fruit cubes with roasted sunflower seeds for the adult; do not offer whole roasted sunflower seeds to the young child", "nourishment_break_b": "A small bowl of curd with a drizzle of honey", "dinner_a": "Roti with a moong-cabbage dal", "dinner_b": "Egg curry with roti and a cabbage sabzi", "still_hungry": "A boiled egg"}, {"day_number": 6, "title": "When to loop in your paediatrician", "notes": "Most food jags are a phase, not a problem. A smaller set of signs is worth a conversation with your child''s paediatrician rather than waiting it out. Worth knowing: Normal growth doesn''t fully rule out a feeding concern — a child can gain weight steadily on a narrow diet. If the accepted range keeps shrinking rather than holding steady or slowly widening, mention that trend even if growth looks fine. For your child: Mention the pattern to your child''s paediatrician if the accepted range remains extremely narrow or keeps shrinking over time — especially if entire food groups or age-appropriate textures are absent, meals regularly cause distress, eating takes unusually long, chewing or swallowing appears difficult, or growth, energy or nutrition is affected. The number of accepted foods can provide useful context, but no single number diagnoses a feeding disorder. Your paediatrician can also refer you to a registered dietitian or a paediatric feeding specialist if the pattern needs a closer look.", "breakfast_a": "Oats chilla with coriander chutney", "breakfast_b": "Egg-and-spinach bhurji with toast", "lunch_a": "Rice with a masoor-toor dal and a pumpkin sabzi", "lunch_b": "Chicken curry with rice and a pumpkin sabzi", "nourishment_break_a": "A bowl of fresh fig halves with roasted walnuts for the adult; do not offer whole roasted walnuts to the young child", "nourishment_break_b": "A glass of buttermilk with a few crushed mint leaves", "dinner_a": "Roti with a chana dal and a spinach sabzi", "dinner_b": "Fish curry with rice and a spinach sabzi", "still_hungry": "A small bowl of curd"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today. What''s the one food that''s carried the last week or two — and is there a new food that''s quietly been sitting next to it, waiting its turn?", "breakfast_a": null, "breakfast_b": null, "lunch_a": null, "lunch_b": null, "nourishment_break_a": null, "nourishment_break_b": null, "dinner_a": null, "dinner_b": null, "still_hungry": null}]'::jsonb,
   'What would it look like to let this phase be exactly that — a phase — rather than a verdict on how your child eats, or how well you''re feeding them?',
